function ff_anychecked(element\x2C message) {
 var name = \x27\x27\x3B
 var cnt = 0\x3B

 /* --- CAS : collection d\x27éléments (plusieurs radios / checkboxes) --- */
 if (!element.name) {
 if (element.length \x26\x26 element.length !== 0) {
 name = element[0].name\x3B
 var i = 0\x3B

 while (i !== element.length) {
 if (element[i].name === name \x26\x26 element[i].checked) {
 cnt++\x3B
 }
 i++\x3B
 }

 if (cnt === 0) {
 ff_validationFocus(element[0].name)\x3B
 if (message === \x27\x27) {
 message = \x22Please check or select \x22 + name + \x22.\x5Cn\x22\x3B
 }
 return message\x3B
 }
 return \x27\x27\x3B
 }
 return \x27\x27\x3B
 }

 /* --- CAS : UN SEUL élément radio / checkbox --- */
 name = element.name\x3B

 if (name.substr(0\x2C 6) === \x27ff_nm_\x27) {
 name = name.substring(6\x2C name.length - 2)\x3B
 }

 if (typeof element.checked !== \x27undefined\x27) {
 if (!element.checked) {
 ff_validationFocus(element.name)\x3B
 if (message === \x27\x27) {
 message = \x22Please check or select \x22 + name + \x22.\x5Cn\x22\x3B
 }
 return message\x3B
 }
 return \x27\x27\x3B
 }

 /* --- CAS : gestion via ff_elements (fallback legacy) --- */
 cnt = 0\x3B
 var i = 0\x3B

 while (i !== ff_elements.length) {
 if (ff_elements[i][2] === name) {
 if (ff_getElementByIndex(i).checked) {
 cnt++\x3B
 }
 }
 i++\x3B
 }

 if (cnt === 0) {
 ff_validationFocus(element.name)\x3B
 if (message === \x27\x27) {
 message = \x22Please check or select \x22 + name + \x22.\x5Cn\x22\x3B
 }
 return message\x3B
 }

 return \x27\x27\x3B
}

function ff_checked(element\x2C message)
{
 if (element.checked) 
 return \x27\x27\x3B 
 else {
 if (message==\x27\x27) message = element.name+\x22 is not checked.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } 
}

function ff_checkedValue(name)
{
 // loop through elements and find checked
 for (i = 0\x3B i \x3C ff_elements.length\x3B i++)
 if (ff_elements[i][2]==name) {
 e = ff_getElementByIndex(i)\x3B
 if (e.checked) return e.value\x3B
 } // if 
 return \x27\x27\x3B
} // ff_checkedValue

function ff_countQuerySelections(name)
{
 var id = ff_getIdByName(name)\x3B
 var cnt = ff_queryRows[id].length\x3B
 var pagesize = ff_queryPageSize[id]\x3B
 if (pagesize\x3E0) {
 var currpage = ff_queryCurrPage[id]\x3B
 var p\x3B
 for (p = 1\x3B p \x3C currpage\x3B p++) cnt -= pagesize\x3B
 if (cnt \x3E pagesize) cnt = pagesize\x3B
 } // if
 var curr\x3B
 var sels = 0\x3B
 for (curr = 0\x3B curr \x3C cnt\x3B curr++)
 if (document.getElementById(\x27ff_cb\x27+id+\x27_\x27+curr).checked) sels++\x3B
 return sels\x3B
} // ff_countQuerySelections

function ff_dollaramount2dp(element\x2C message)
{
 var ex = /^\x5Cd+$|^\x5Cd+\x5C.\x5Cd{2}$/\x3B
 if (!ex.test(element.value)) {
 if (message==\x27\x27) message = element.name+\x22 must be a number with two decimal places.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } // if
 return \x27\x27\x3B
} // ff_dollaramount2dp

function ff_expString(text)
{
 text = trim(text)\x3B
 var i\x3B
 var o = \x27\x27\x3B
 for(i = 0\x3B i \x3C text.length\x3B i++) {
 c = text.charAt(i)\x3B
 switch(c) {
 case \x27\x3B\x27 : o += \x27\x5C\x5Cx3B\x27\x3B break\x3B
 case \x27\x2C\x27 : o += \x27\x5C\x5Cx2C\x27\x3B break\x3B
 case \x27\x26\x27 : o += \x27\x5C\x5Cx26\x27\x3B break\x3B
 case \x27\x3C\x27 : o += \x27\x5C\x5Cx3C\x27\x3B break\x3B
 case \x27\x3E\x27 : o += \x27\x5C\x5Cx3E\x27\x3B break\x3B
 case \x27\x5C\x27\x27: o += \x27\x5C\x5Cx27\x27\x3B break\x3B
 case \x27\x5C\x5C\x27: o += \x27\x5C\x5Cx5C\x27\x3B break\x3B
 case \x27\x22\x27 : o += \x27\x5C\x5Cx22\x27\x3B break\x3B
 case \x27\x5Cn\x27: o += \x27\x5C\x5Cn\x27\x3B break\x3B
 case \x27\x5Cr\x27: o += \x27\x5C\x5Cr\x27\x3B break\x3B
 default: o += c\x3B
 } // switch
 } // for
 return o\x3B
} // expString

function ff_flashupload_not_empty(element\x2C message)
{
 if (typeof bfSummarizers == \x22undefined\x22) { 
 if (typeof bfUseErrorAlerts == \x27undefined\x27){
 alert(\x22Flash upload validation only available in QuickMode!\x22)\x3B
 } else {
 alert(\x22Flash upload validation only available in QuickMode!\x22)\x3B
 } 
 return \x27\x27\x3B}
 if (JQuery(\x27#bfFlashFileQueue\x27+element.id.split(\x27ff_elem\x27)[1]).html() != \x27\x27) return \x27\x27\x3B
 if (message==\x27\x27) message = \x22Please enter \x22+element.name+\x22.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
} // ff_valuenotempty

function ff_getfocus(element\x2Ccondition)
{
 if (!element.name){
 if (element.length \x26\x26 element.length != 0){
 element[0].focus()\x3B
 }
 }else{
 element.focus()\x3B
 }
}

function ff_getQuerySelectedRows(name)
{
 var id = ff_getIdByName(name)\x3B
 var rcnt = ff_queryRows[id].length\x3B
 var cnt = rcnt\x3B
 var pagesize = ff_queryPageSize[id]\x3B
 if (pagesize\x3E0) {
 var currpage = ff_queryCurrPage[id]\x3B
 var p\x3B
 for (p = 1\x3B p \x3C currpage\x3B p++) cnt -= pagesize\x3B
 if (cnt \x3E pagesize) cnt = pagesize\x3B
 } // if
 var curr\x2C r\x3B
 var selcnt = 0\x3B
 var sels = new Array\x3B
 for (curr = 0\x3B curr \x3C cnt\x3B curr++) {
 var elem = document.getElementById(\x27ff_cb\x27+id+\x27_\x27+curr)\x3B
 if (elem.checked) {
 var ident = elem.value\x3B
 for (r = 0\x3B r \x3C rcnt\x3B r++)
 if (ff_queryRows[id][r][0] == ident) {
 sels[selcnt++] = ff_queryRows[id][r]\x3B
 break\x3B
 } // if
 } // if
 } // for
 return sels\x3B
} // ff_getQuerySelectedRows

function ff_getQuerySelections(name)
{
 var id = ff_getIdByName(name)\x3B
 var cnt = ff_queryRows[id].length\x3B
 var pagesize = ff_queryPageSize[id]\x3B
 if (pagesize\x3E0) {
 var currpage = ff_queryCurrPage[id]\x3B
 var p\x3B
 for (p = 1\x3B p \x3C currpage\x3B p++) cnt -= pagesize\x3B
 if (cnt \x3E pagesize) cnt = pagesize\x3B
 } // if
 var curr\x3B
 var selcnt = 0\x3B
 var sels = new Array\x3B
 for (curr = 0\x3B curr \x3C cnt\x3B curr++) {
 var elem = document.getElementById(\x27ff_cb\x27+id+\x27_\x27+curr)\x3B
 if (elem.checked) 
 sels[selcnt++] = elem.value\x3B
 } // for
 return sels\x3B
} // ff_getQuerySelections

function ff_htmlvaluenotempty( element\x2C message ){
 
 if ( typeof bf_htmltextareanames == \x22undefined\x22 ) return \x27\x27\x3B

 var content = \x22\x22\x3B

 for(var i = 0\x3B i \x3C bf_htmltextareanames.length\x3B i++){
 if ( element.name == bf_htmltextareanames[i] ) {
 eval(\x22content = \x22 + bf_htmltextareas[i])\x3B
 break\x3B
 }
 }
 if (JQuery.trim(content) == \x22\x22) {
 if (message==\x27\x27) message = element.name+\x22 must not be empty.\x5Cn\x22\x3B
 return message\x3B
 } // if
 return \x27\x27\x3B
}

function ff_impString(text)
{
 var str = \x27\x27\x3B
 var ss = 0\x3B
 var s\x3B
 var tl = text.length\x3B
 var hexdigs = \x220123456789abcdefABCDEF\x22\x3B
 while (ss \x3C tl) {
 s = text.charAt(ss++)\x3B
 if (s == \x27\x5C\x5C\x27) {
 if (ss \x3C tl) s = text.charAt(ss++)\x3B else s = 0\x3B
 switch (s) {
 case 0 : break\x3B
 case \x27e\x27 : str += \x27\x5C33\x27\x3B break\x3B
 case \x27t\x27 : str += \x27\x5Ct\x27\x3B break\x3B
 case \x27r\x27 : str += \x27\x5Cr\x27\x3B break\x3B
 case \x27n\x27 : str += \x27\x5Cn\x27\x3B break\x3B
 case \x27f\x27 : str += \x27\x5Cf\x27\x3B break\x3B
 case \x27x\x27 : {
 if (ss \x3C tl) s = text.charAt(ss++)\x3B else s = 0\x3B
 var ch = \x27\x27\x3B
 while (hexdigs.indexOf(s)\x3E=0 \x26\x26 ch.length \x3C 2) {
 ch += s\x3B
 if (ss \x3C tl) s = text.charAt(ss++)\x3B else s = 0\x3B
 } // while
 while (ch.length \x3C 2) ch = \x270\x27+ch\x3B
 str += unescape(\x27%\x27+ch)\x3B
 if (s) ss--\x3B
 break\x3B
 }
 default:
 str += s\x3B
 } // switch
 } else
 str += s\x3B
 } // while
 return str\x3B
} // impString

function ff_integer(element\x2C message)
{
 var ex = /(^-?\x5Cd\x5Cd*$)/\x3B
 if (!ex.test(element.value)) {
 if (message==\x27\x27) message = element.name+\x22 must be integer.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } // if
 return \x27\x27\x3B
} // ff_integer

