function ff_MaxCheckedInGroups(element\x2C message)
{ 
 // setup
 let fields = [\x27group1\x27\x2C \x27group2\x27\x2C \x27group3\x27\x2C \x27group4\x27\x2C \x27group5\x27]\x3B
 let max_checked = 20\x3B

 // actual calculation
 let checked_length = 0\x3B

 for(let i = 0\x3B i \x3C fields.length\x3B i++){
 let checkboxes = JQuery(\x22[name=\x5C\x22ff_nm_\x22+fields[i]+\x22[]\x5C\x22]:checked\x22)\x3B
 checked_length += checkboxes.length\x3B
 }

 if (checked_length == 0 || checked_length \x3E max_checked){
 if (message==\x27\x27) message = element.name+\x22 faild in my test.\x5Cn\x22
 ff_validationFocus(element.name)\x3B
 return message\x3B
 }
 else {
 return \x27\x27\x3B
 }
}

function ff_nextpage(element\x2C action)
{
 if (ff_currentpage \x3C ff_lastpage) {
 ff_switchpage(ff_currentpage+1)\x3B
 self.scrollTo(0\x2C0)\x3B
 }
} // ff_nextpage

function ff_page1(element\x2C action)
{
 ff_switchpage(1)\x3B
} // ff_page1

function ff_page2(element\x2C action)
{
 if (ff_lastpage \x3E= 2) ff_switchpage(2)\x3B
} // ff_page2

function ff_page3(element\x2C action)
{
 if (ff_lastpage \x3E= 3) ff_switchpage(3)\x3B
} // ff_page3

function ff_previouspage(element\x2C action)
{
 if (ff_currentpage \x3E 1){
 ff_switchpage(ff_currentpage-1)\x3B
 self.scrollTo(0\x2C0)\x3B
 }
} // ff_previouspage

