function ff_resetForm(element\x2C action) {
 // Accéder au formulaire directement par son ID sans utiliser eval
 var form = document.getElementById(ff_processor.form_id)\x3B
 
 // Si le formulaire est trouvé\x2C le réinitialiser
 if (form) {
 form.reset()\x3B
 } else {
 console.error(\x27Formulaire non trouvé avec l\x5C\x27ID:\x27\x2C ff_processor.form_id)\x3B
 }
}
