script.description:
Get values of selected options of a select list as list:

x = ff_selectedValues(\x27myselectlist\x27)\x3B
// x = green\x2Cred

script.code:
function ff_selectedValues(name) {
 let vals = \x27\x27\x3B // Variable pour stocker les valeurs sélectionnées
 let element = ff_getElementByName(name)\x3B // Récupérer l\x27élément par son nom

 // Si l\x27élément est une case à cocher
 if (element.tagName.toLowerCase() === \x27input\x27 \x26\x26 element.type === \x27checkbox\x27) {
 // Sélectionner les checkboxes avec le nom spécifié et qui sont cochées
 var checkboxes = document.querySelectorAll(\x27input[name=\x22ff_nm_\x27 + name + \x27[]\x22]:checked\x27)\x3B
 
 // Vérifier s\x27il y a des checkboxes sélectionnées
 if (checkboxes.length === 0) {
 console.warn(\x22Aucune case sélectionnée pour le nom: \x22 + name)\x3B
 return \x27\x27\x3B // Retourner une chaîne vide si aucune case n\x27est sélectionnée
 }

 // Récupérer les valeurs sélectionnées\x2C supprimer les espaces superflus\x2C et les joindre par des virgules
 vals = Array.from(checkboxes)
 .map((checkbox) =\x3E checkbox.value.trim()) // Utilisation de trim pour éliminer les espaces
 .join(\x27\x2C\x27)\x3B

 } else if (element.tagName.toLowerCase() === \x27select\x27) {
 // Si l\x27élément est une liste déroulante
 let opts = element.options\x3B // Récupérer les options de la liste déroulante
 for (let o = 0\x3B o \x3C opts.length\x3B o++) {
 // Si l\x27option est sélectionnée\x2C on l\x27ajoute aux valeurs
 if (opts[o].selected) {
 if (vals !== \x27\x27) vals += \x27\x2C\x27\x3B // Ajouter une virgule entre les valeurs
 vals += opts[o].value\x3B // Ajouter la valeur de l\x27option
 }
 }
 }

 return vals\x3B // Retourner les valeurs sous forme de chaîne séparée par des virgules
}

