 if (JQuery(\x22#bfFileQueue\x22).size() \x3E 0 \x26\x26 typeof bfAjaxObject101 == \x27undefined\x27 \x26\x26 typeof bfReCaptchaLoaded == \x27undefined\x27)
 {
 bfDoFlashUploadAjax()\x3B


 }else{

