 function bfDoFlashUploadAjax(element){
 JQuery(\x22#bfSubmitMessage\x22).css(\x22visibility\x22\x2C\x22hidden\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22display\x22\x2C\x22none\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22z-index\x22\x2C\x22999999\x22)\x3B
 JQuery(\x22.bfErrorMessage\x22).html(\x22\x22)\x3B
 JQuery(\x22.bfErrorMessage\x22).css(\x22display\x22\x2C\x22none\x22)\x3B
 for(var i = 0\x3B i \x3C bfUploaderErrorElements.length\x3B i++){
 JQuery(\x22#\x22+bfUploaderErrorElements[i]).html(\x22\x22)\x3B
 }
 bfUploaderErrorElements = []\x3B
 if (ff_validation(0) == \x22\x22){
 try{
 bfFlashUploadInterval = window.setInterval( bfCheckFlashUploadProgressAjax\x2C 1000 )\x3B
 if (bfFlashUploadersLength \x3E 0){
 JQuery(\x22#bfFileQueue\x22).bfcenter(true)\x3B
 JQuery(\x22#bfFileQueue\x22).css(\x22visibility\x22\x2C\x22visible\x22)\x3B
 for( var i = 0\x3B i \x3C bfUploaders.length\x3B i++ ){
 bfUploaders[i].start()\x3B
 }
 }
 } catch(e){alert(e)}
 } else {
 if (typeof bfUseErrorAlerts == \x22undefined\x22){
 alert(error)\x3B
 } else {
 bfShowErrors(error)\x3B
 }
 ff_validationFocus(\x22\x22)\x3B
 if (document.getElementById(\x22bfSubmitButton\x22)) {
 document.getElementById(\x22bfSubmitButton\x22).disabled = false\x3B
 }
 }
 }
 function bfCheckFlashUploadProgressAjax(){
 if ( JQuery(\x22#bfFileQueue\x22).html() == \x22\x22 ){ // empty indicates that all queues are uploaded or in any way cancelled
 JQuery(\x22#bfFileQueue\x22).css(\x22visibility\x22\x2C\x22hidden\x22)\x3B
 window.clearInterval( bfFlashUploadInterval )\x3B
 if (typeof bfAjaxObject101 != \x27undefined\x27 || typeof bfReCaptchaLoaded != \x27undefined\x27){
 ff_submitForm2()\x3B
 }else{
 ff_validate_submitAjax()\x3B
 }
 JQuery(\x22.bfFlashFileQueueClass\x22).html(\x22\x22)\x3B
 if (bfFlashUploadersLength \x3E 0){
 JQuery(\x22#bfSubmitMessage\x22).bfcenter(true)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22visibility\x22\x2C\x22visible\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22display\x22\x2C\x22block\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22z-index\x22\x2C\x22999999\x22)\x3B
 }

 }
 }

 function bf_ajax_submit(){

 JQuery.ajax({
 type: \x22POST\x22\x2C
 url: JQuery(bfAjaxSubmitElement).closest(\x22form\x22).attr(\x22action\x22)\x2C
 data: JQuery(bfAjaxSubmitElement).closest(\x22form\x22).serialize()\x2C
 success: function(data)
 {
 JQuery(\x22#bfSubmitMessage\x22).css(\x22visibility\x22\x2C\x22hidden\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22display\x22\x2C\x22none\x22)\x3B
 JQuery(\x22#bfSubmitMessage\x22).css(\x22z-index\x22\x2C\x22999999\x22)\x3B

 // assuming last page is thank you page
 if (document.getElementById(\x22bfPage\x22 + (ff_currentpage + 1))
 \x26\x26 document.getElementById(\x22bfPage\x22 + (ff_currentpage + 1)).style.display == \x27none\x27){

 ff_switchpage(ff_currentpage + 1)\x3B

 }
 else{

 alert(\x27Successfully submitted\x27)\x3B
 window.location = window.location.href\x3B
 }
 }
 })\x3B

 }

function ff_validemail(element\x2C message)
{
 var check =
 /^([a-zA-Z0-9_\x5C.\x5C-])+\x5C@(([a-zA-Z0-9\x5C-])+\x5C.)+([a-zA-Z0-9]{2\x2C4})+$/\x3B
 if (!check.test(element.value)){
 if (message==\x27\x27) message = element.name+\x22 is no valid email address.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } // if
 return \x27\x27\x3B
} // ff_validemail

function ff_validemail_repeat(element\x2C message)
{
 var check =
 /^([a-zA-Z0-9_\x5C.\x5C-])+\x5C@(([a-zA-Z0-9\x5C-])+\x5C.)+([a-zA-Z0-9]{2\x2C4})+$/\x3B
 if (!check.test(element.value)){
 if (message==\x27\x27) message = element.name+\x22 is no valid email address.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } // if
 
 try{
 var repeat = element.name.split(\x22ff_nm_\x22)[1].split(\x22[]\x22)[0]\x3B
 
 if (!ff_getElementByName(repeat + \x27_repeat\x27)){
 if (message==\x27\x27) message = repeat+\x22 has no repeat email field.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
 } else {
 if (ff_getElementByName(repeat + \x27_repeat\x27).value != element.value){
 if (message==\x27\x27) message = element.name+\x22 and \x22 + repeat + \x22_repeat do not match.\x5Cn\x22\x3B
 ff_validationFocus(repeat + \x27_repeat\x27)\x3B
 return message\x3B
 }
 }
 }catch(e){
 return e.description\x3B
 }

 return \x27\x27\x3B
} // ff_validemail

function ff_valuenotempty(element\x2C message)
{
 if (element.value!=\x27\x27) return \x27\x27\x3B 
 if (message==\x27\x27) message = \x22Please enter \x22+element.name+\x22.\x5Cn\x22\x3B
 ff_validationFocus(element.name)\x3B
 return message\x3B
} // ff_valuenotempty

