script.description:
Format \x22 Adresse \x22
Format FR\x2C ex.: rue de la Mairie\x2C allée aux ... \x2C de la

// ------------------------------------------------------------
// gn_format_address_fr
// Format French address (street + number)
//
// Examples:
// - \x2212 RUE DE la mairie\x22 -\x3E \x2212 rue de la Mairie\x22
// - \x225bis ALLEE des ACACIAS\x22 -\x3E \x225bis allée des Acacias\x22
// - \x22 3\x2C rue d\x27alsace-lorraine \x22 -\x3E \x223\x2C rue d\x27Alsace-Lorraine\x22
//
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_adresse(str)
{
 var v = String(str || \x27\x27)\x3B

 // Trim + collapse spaces
 v = v.replace(/^\x5Cs+|\x5Cs+$/g\x2C \x27\x27)\x3B
 v = v.replace(/\x5Cs+/g\x2C \x27 \x27)\x3B

 if (v === \x27\x27) return \x27\x27\x3B

 // Lowercase base (we will capitalize words)
 v = v.toLowerCase()\x3B

 // Split by spaces (simple)
 var parts = v.split(\x27 \x27)\x3B

 // Words that should stay lowercase (unless first word)
 var small = {
 \x27de\x27:1\x2C\x27du\x27:1\x2C\x27des\x27:1\x2C\x27la\x27:1\x2C\x27le\x27:1\x2C\x27les\x27:1\x2C\x27d\x27:1\x2C\x27l\x27:1\x2C
 \x27et\x27:1\x2C\x27aux\x27:1\x2C\x27au\x27:1\x2C\x27en\x27:1\x2C\x27sur\x27:1\x2C\x27sous\x27:1\x2C\x27chez\x27:1
 }\x3B

 // Helper: capitalize first letter of a word (keeps the rest)
 function capWord(w) {
 if (!w) return w\x3B
 return w.charAt(0).toUpperCase() + w.substring(1)\x3B
 }

 // Helper: capitalize subparts separated by \x27-\x27 (Saint-Quentin)
 function capHyphen(w) {
 var sub = w.split(\x27-\x27)\x3B
 for (var i = 0\x3B i \x3C sub.length\x3B i++) {
 if (sub[i]) sub[i] = capWord(sub[i])\x3B
 }
 return sub.join(\x27-\x27)\x3B
 }

 // Helper: handle apostrophe (d\x27alsace -\x3E d\x27Alsace)
 function capApostrophe(w) {
 var apos = w.indexOf(\x22\x27\x22)\x3B
 if (apos \x3E 0 \x26\x26 apos \x3C w.length - 1) {
 var left = w.substring(0\x2C apos)\x3B
 var right = w.substring(apos + 1)\x3B
 // left stays lowercase (d\x27\x2C l\x27)
 return left + \x22\x27\x22 + capHyphen(capWord(right))\x3B
 }
 return capHyphen(capWord(w))\x3B
 }

 // Process words
 for (var p = 0\x3B p \x3C parts.length\x3B p++) {
 var w = parts[p]\x3B

 // Keep empty
 if (!w) continue\x3B

 // Keep pure numbers / house numbers as-is (example: 12\x2C 12bis\x2C 3/5)
 // (do not change case)
 // We simply avoid lowercasing letters in \x22bis/ter\x22 if user typed them.
 // But since we lowercased earlier\x2C that\x27s OK: \x2212BIS\x22 -\x3E \x2212bis\x22
 var hasDigit = (w.indexOf(\x270\x27)\x3E=0||w.indexOf(\x271\x27)\x3E=0||w.indexOf(\x272\x27)\x3E=0||w.indexOf(\x273\x27)\x3E=0||w.indexOf(\x274\x27)\x3E=0||
 w.indexOf(\x275\x27)\x3E=0||w.indexOf(\x276\x27)\x3E=0||w.indexOf(\x277\x27)\x3E=0||w.indexOf(\x278\x27)\x3E=0||w.indexOf(\x279\x27)\x3E=0)\x3B

 // Handle small words (keep lowercase\x2C unless first word)
 if (p !== 0) {
 // also handle \x22d\x27\x22 / \x22l\x27\x22
 if (w === \x22d\x22 || w === \x22l\x22) { parts[p] = w\x3B continue\x3B }
 if (small[w]) { parts[p] = w\x3B continue\x3B }
 if (w.indexOf(\x22d\x27\x22) === 0 || w.indexOf(\x22l\x27\x22) === 0) {
 parts[p] = capApostrophe(w)\x3B
 continue\x3B
 }
 }

 // Otherwise: capitalize (with hyphen / apostrophe support)
 if (w.indexOf(\x22\x27\x22) !== -1) {
 parts[p] = capApostrophe(w)\x3B
 } else if (w.indexOf(\x27-\x27) !== -1) {
 parts[p] = capHyphen(w)\x3B
 } else if (!hasDigit) {
 parts[p] = capWord(w)\x3B
 } else {
 parts[p] = w\x3B // house number: keep as is
 }
 }

 // Rebuild
 return parts.join(\x27 \x27)\x3B
}

script.description:
Format \x22 Code Postal \x22
Format FR\x2C ex.: 78180\x2C 5 chiffres

// ------------------------------------------------------------
// gn_format_codepostal
// Format French postal code (5 digits)
//
// Rules:
// - Keep digits only
// - Expected length = 5
// - No hard error (BF-friendly)
// - Debug: IN / OUT
//
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_code_postal(input)
{
 console.log(\x27[CP] IN =\x27\x2C input)\x3B

 // Keep digits only
 var v = String(input || \x27\x27).replace(/[^0-9]/g\x2C \x27\x27)\x3B

 // Optional: limit to 5 digits max
 if (v.length \x3E 5) {
 v = v.substring(0\x2C 5)\x3B
 }

 console.log(\x27[CP] OUT =\x27\x2C v)\x3B
 return v\x3B
} // gn_format_code_postal

script.description:
Format \x22 VCMB Coordonnées \x22 each element based on its BF element name: 
Nom\x2C Prenom\x2C Email\x2C Telephone\x2C DateNaissance\x2C Adresse\x2C CodePostal\x2C Ville\x2C
It may call a \x22 gn_format_xxx \x22 spécialized functions

// ------------------------------------------------------------
// gn_format_coordonnees
// MAIN dispatcher for formatting VCMB form fields
//
// Fields handled (BF logical names):
// Nom\x2C Prenom\x2C Email\x2C Telephone\x2C DateNaissance\x2C Adresse (numéro + rue)\x2C CodePostal\x2C Ville
//
// Call from each BF element:
// Advanced / Actionscript / Ligrary / \x27Change\x27 / \x27gn_format_coordonnees\x27
// or Advanced / Actionscript / Custom / Change / function () 
//
// Debug: Console only (F12)\x2C Enable (true) / disable (false) with GN_DEBUG flag
//
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_coordonnees(element) {

 // -------------------------
 // Debug switch : false (default) or true
 // -------------------------
 var GN_DEBUG = true\x3B

 // DEBUG : Simple console debug helper
 function debug(msg) {
 if (GN_DEBUG \x26\x26 window.console) {
 console.log(\x27[gn_format_coordonnees] \x27 + msg)\x3B
 }
 } // debug

 // -------------------------
 // Safety check: element
 // -------------------------
 // BF should always pass the DOM element (this)\x2C
 // but we protect against misconfiguration
 if (!element) {
 debug(\x27ERROR: element is undefined\x27)\x3B
 return\x3B
 }

 // -------------------------
 // Get BF logical field name
 // -------------------------
 // IMPORTANT:
 // element.name -\x3E HTML name (ex: ff_nm_Nom[])
 // We need the BF logical name (ex: Nom)
 var field = gn_getBFElementName(element)\x3B

 if (!field) {
 debug(\x27ERROR: cannot resolve BF field name\x27)\x3B
 return\x3B
 }

 // -------------------------
 // Raw value from field
 // -------------------------
 var raw = (typeof element.value === \x27string\x27) ? element.value : \x27\x27\x3B
 debug(\x27Field=\x22\x27 + field + \x27\x22 | Raw=\x22\x27 + raw + \x27\x22\x27)\x3B

 // -------------------------
 // Base normalization
 // -------------------------
 // Trim + normalize spaces (common to all fields)
 var v = gn_format_trimSpaces(raw)\x3B
 debug(\x27After trimSpaces=\x22\x27 + v + \x27\x22\x27)\x3B

 // -------------------------
 // Dispatch formatting by field
 // -------------------------
 switch (field) {

 // ---------------------
 // NOM (uppercase)
 // ---------------------
 case \x27Nom\x27:
 v = v.toUpperCase()\x3B
 element.value = v\x3B
 debug(\x27Nom formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // PRENOM (simple for now)
 // ---------------------
 case \x27Prenom\x27:
 // Format Prenom according to FR rules
 v = gn_format_prenom(v)\x3B
 element.value = v\x3B
 debug(\x27Prenom formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // EMAIL (lowercase)
 // ---------------------
 case \x27Email\x27:
 // Email Format et check security
 v = gn_format_email(v)\x3B
 element.value = v\x3B
 debug(\x27Email formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // TELEPHONE (digits\x2C FR rules later)
 // ---------------------
 case \x27Telephone\x27:
 // Format téléphone (FR) : +33 6\x2C 06 78 78 44 55
 v = gn_format_telephone(v)\x3B
 element.value = v\x3B
 debug(\x27Telephone formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // DATE DE NAISSANCE
 // Expected: JJ/MM/AAAA
 // ---------------------
 case \x27DateNaissance\x27:
 // Format (FR) : 23/01/2004 ou 23-01-2004
 v = gn_format_date_naissance(v)\x3B
 element.value = v\x3B
 debug(\x27Date de naissance formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // ADRESSE (numéro + rue)
 // ---------------------
 case \x27Adresse\x27:
 // Format : rue de la Mairie (le\x2C les\x2C rue\x2C allée\x2C ...)
 v = gn_format_adresse(v)\x3B
 element.value = v\x3B
 debug(\x27Adresse formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // CODE POSTAL (FR = 5 digits)
 // ---------------------
 case \x27CodePostal\x27:
 // Format : 5 chiffres
 v = gn_format_code_postal(v)\x3B
 element.value = v\x3B
 debug(\x27CodePostal formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // VILLE
 // ---------------------
 case \x27Ville\x27:
 // Format : \x22 Montigny-le-Bretonneux\x2C Les Essarts-le-Roi\x2C Saint-Germain-en-Laye\x2C ... \x22
 v = gn_format_ville(v)\x3B
 element.value = v\x3B
 debug(\x27Ville formatted =\x3E \x22\x27 + v + \x27\x22\x27)\x3B
 break\x3B

 // ---------------------
 // Unknown / not handled
 // ---------------------
 default:
 debug(\x27No formatter defined for field=\x22\x27 + field + \x27\x22\x27)\x3B
 break\x3B
 }
} // gn_format_coordonnees

script.description:
Format \x22 Date de Naissance \x22 (FR)
Output: DD/MM/YYYY
Ex.: 23/01/2004 ou 23-01-2004 ou 23/01/04 

// Format French birth date
// Accepted input: DD/MM/YYYY\x2C DD/MM/YY ou DD-MM-YYYY
// False return \x27\x27 (vide)
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 24/03/2026

script.code:
/**
 * ------------------------------------------------
 * gn_format_date_naissance(str)
 * ------------------------------------------------
 * Normalise une date de naissance au format :
 * JJ/MM/AAAA
 *
 * Exemples :
 * \x2712 / 02 / 2023 \x27 -\x3E \x2712/02/2023\x27
 * \x2712/2/23\x27 -\x3E \x2712/02/2023\x27
 * \x2712-2-23\x27 -\x3E \x2712/02/2023\x27
 * \x2712-2-93\x27 -\x3E \x2712/02/1993\x27
 * \x2731/02/2003\x27 -\x3E \x27\x27
 * \x271A/01/2030\x27 -\x3E \x27\x27
 *
 * Règles :
 * - accepte séparateurs \x22/\x22 ou \x22-\x22
 * - supprime les espaces inutiles
 * - année sur 2 chiffres :
 * si \x3C= année courante sur 2 chiffres =\x3E 2000 + AA
 * sinon =\x3E 1900 + AA
 * - refuse toute date dans le futur
 * - exception : toute date en 2099 est autorisée (back door bénévole)
 * - vérifie la validité réelle de la date
 * - retourne \x27\x27 si invalide
 * ------------------------------------------------
 */
function gn_format_date_naissance(str)
{
 var GN_DEBUG = false\x3B // true\x2C false en production

 function dbg(msg)
 {
 if (GN_DEBUG) {
 alert(\x27[gn_format_date_naissance] \x27 + msg)\x3B
 }
 }

 // ------------------------------------------------
 // sécurité sur valeur absente
 // ------------------------------------------------
 if (str === null || str === undefined) {
 dbg(\x27valeur null ou undefined\x27)\x3B
 return \x27\x27\x3B
 }

 // conversion en chaîne + trim
 str = String(str).trim()\x3B

 if (str === \x27\x27) {
 dbg(\x27chaine vide\x27)\x3B
 return \x27\x27\x3B
 }

 dbg(\x27entrée = \x27 + str)\x3B

 // ------------------------------------------------
 // nettoyage
 // ------------------------------------------------
 // supprime tous les espaces : \x2212 / 2 / 23\x22 =\x3E \x2212/2/23\x22
 str = str.replace(/\x5Cs+/g\x2C \x27\x27)\x3B

 // uniformise les séparateurs : \x2212-2-23\x22 =\x3E \x2212/2/23\x22
 str = str.replace(/-/g\x2C \x27/\x27)\x3B

 dbg(\x27normalisé = \x27 + str)\x3B

 // ------------------------------------------------
 // extraction des 3 blocs numériques
 // refuse par ex : \x221A/01/2030\x22
 // ------------------------------------------------
 var m = str.match(/^(\x5Cd{1\x2C2})\x5C/(\x5Cd{1\x2C2})\x5C/(\x5Cd{2}|\x5Cd{4})$/)\x3B

 if (!m) {
 dbg(\x27format invalide\x27)\x3B
 return \x27\x27\x3B
 }

 var jour = parseInt(m[1]\x2C 10)\x3B
 var mois = parseInt(m[2]\x2C 10)\x3B
 var anneeTxt = m[3]\x3B
 var annee = parseInt(anneeTxt\x2C 10)\x3B

 dbg(\x27jour=\x27 + jour + \x27 mois=\x27 + mois + \x27 anneeTxt=\x27 + anneeTxt)\x3B

 // ------------------------------------------------
 // conversion année sur 2 chiffres
 // pivot = année actuelle
 // ex en 2026 :
 // 26 =\x3E 2026
 // 27 =\x3E 1927
 // ------------------------------------------------
 var now = new Date()\x3B
 var anneeCourante = now.getFullYear()\x3B
 var anneeCourteCourante = anneeCourante % 100\x3B

 if (anneeTxt.length === 2) {
 if (annee \x3C= anneeCourteCourante) {
 annee = 2000 + annee\x3B
 } else {
 annee = 1900 + annee\x3B
 }

 dbg(\x27année convertie = \x27 + annee)\x3B
 }

 // ------------------------------------------------
 // contrôles simples
 // ------------------------------------------------
 if (mois \x3C 1 || mois \x3E 12) {
 dbg(\x27mois invalide\x27)\x3B
 return \x27\x27\x3B
 }

 if (jour \x3C 1 || jour \x3E 31) {
 dbg(\x27jour invalide\x27)\x3B
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // vérification réelle de la date
 // gère automatiquement :
 // - mois 30/31 jours
 // - février
 // - 29 février année bissextile
 // ------------------------------------------------
 var d = new Date(annee\x2C mois - 1\x2C jour)\x3B

 if (
 d.getFullYear() !== annee ||
 d.getMonth() !== (mois - 1) ||
 d.getDate() !== jour
 ) {
 dbg(\x27date impossible\x27)\x3B
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // refuse une date future complète
 // sauf exception spéciale année 2099
 // ------------------------------------------------
 if (annee !== 2099) {
 var dateSaisie = new Date(annee\x2C mois - 1\x2C jour)\x3B
 var dateAujourdhui = new Date(
 now.getFullYear()\x2C
 now.getMonth()\x2C
 now.getDate()
 )\x3B

 if (dateSaisie.getTime() \x3E dateAujourdhui.getTime()) {
 dbg(\x27date dans le futur\x27)\x3B
 return \x27\x27\x3B
 }
 } else {
 dbg(\x27exception 2099 autorisée\x27)\x3B
 }

 // ------------------------------------------------
 // format final JJ/MM/AAAA
 // ------------------------------------------------
 var jj = String(jour).padStart(2\x2C \x270\x27)\x3B
 var mm = String(mois).padStart(2\x2C \x270\x27)\x3B
 var aaaa = String(annee)\x3B

 var res = jj + \x27/\x27 + mm + \x27/\x27 + aaaa\x3B

 dbg(\x27résultat = \x27 + res)\x3B

 return res\x3B
}

script.description:
Format \x22 Email \x22
Format a first name
Ex.: Jean-Luc\x2C Bernard\x2C Marie-Claire\x2C D\x27Arcy\x2C O\x27Neill

// Simple \x26 BF-safe email cleanup + basic checks (not full RFC)
// - trim + remove spaces
// - lowercase
// - basic structure checks: one \x27@\x27\x2C domain has a \x27.\x27\x2C etc.
// - optional: remove a few dangerous characters
//
// Returns a cleaned email string.
// If something looks wrong\x2C returns the cleaned string anyway\x2C
// and you can display a debug message.
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_email(str)
{
 var v = String(str || \x27\x27)\x3B

 // Trim (ES5 safe)
 v = v.replace(/^\x5Cs+|\x5Cs+$/g\x2C \x27\x27)\x3B

 // Remove ALL spaces (email must not contain spaces)
 v = v.replace(/\x5Cs+/g\x2C \x27\x27)\x3B

 // Lowercase
 v = v.toLowerCase()\x3B

 // Remove a few characters that can break HTML/headers/scripts (BF safe)
 // (No \x3C or \x3E literal to avoid BF filtering)
 v = v.replace(/[\x5Cx3C\x5Cx3E\x22\x27\x5C(\x5C)\x5C[\x5C]\x5C\x5C\x2C\x3B:]/g\x2C \x27\x27)\x3B

 return v\x3B
 
} // gn_format_email

script.description:
Format \x22 Prénom \x22
Format a first name
Ex.: Jean-Luc\x2C Bernard\x2C Marie-Claire\x2C D\x27Arcy\x2C O\x27Neill

// Format a first name (Prénom)
// Rules:
// - Trim spaces
// - Convert spaces to single hyphen
// - First letter uppercase\x2C rest lowercase
// - Handle composed first names 
// Ex.: Jean-Luc\x2C Bernard\x2C Marie-Claire\x2C D\x27Arcy\x2C O\x27Neill
// BF / Joomla 6 safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_prenom(str)
{
 if (!str) return \x27\x27\x3B

 // 1) Normalize spaces
 var v = gn_format_trimSpaces(str)\x3B

 // 2) Replace spaces by hyphen (prenom composé)
 v = v.replace(/\x5Cs+/g\x2C \x27-\x27)\x3B

 // 3) Lowercase everything first
 v = v.toLowerCase()\x3B

 // 4) Uppercase first letter and letter after hyphen
 v = v.replace(/(^|-)([a-zà-ÿ])/g\x2C function(match\x2C sep\x2C letter) {
 return sep + letter.toUpperCase()\x3B
 })\x3B

 return v\x3B
} // gn_format_prenom

script.description:
Format \x22 Téléphone\x22 (FR)
Retour\x2C exemple : 06 78 78 44 55

// Simple \x26 safe phone formatter (FR-first logic)
//
// Rules:
// - Keep digits\x2C keep \x27+\x27 only if first char
// - If no leading 0 → add one
// - If 10 digits → group by 2 with spaces
// - If too long → error message
// - Debug: 2 console lines (IN / OUT)
//
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026
// ------------------------------------------------------------

script.code:
function gn_format_telephone(input)
{
 console.log(\x27[TEL] IN =\x27\x2C input)\x3B

 var s = String(input || \x27\x27).trim()\x3B
 var hasPlus = (s.charAt(0) === \x27+\x27)\x3B

 // Keep digits\x2C keep \x27+\x27 only if first char
 var cleaned = \x27\x27\x3B
 for (var i = 0\x3B i \x3C s.length\x3B i++) {
 var c = s.charAt(i)\x3B
 if (c \x3E= \x270\x27 \x26\x26 c \x3C= \x279\x27) {
 cleaned += c\x3B
 } else if (i === 0 \x26\x26 c === \x27+\x27) {
 cleaned += c\x3B
 }
 }

 // Count digits only
 var digits = cleaned.replace(/[^0-9]/g\x2C \x27\x27)\x3B

 // Security: too long → reject
 if (digits.length \x3E 15) {
 console.log(\x27[TEL] OUT = Erreur n° de téléphone\x27)\x3B
 return \x27Erreur n° de téléphone\x27\x3B
 }

 // Remove \x27+\x27 for formatting logic
 if (hasPlus) {
 cleaned = cleaned.substring(1)\x3B
 digits = cleaned.replace(/[^0-9]/g\x2C \x27\x27)\x3B
 }

 // If no leading 0\x2C add one (FR logic)
 if (digits.charAt(0) !== \x270\x27) {
 digits = \x270\x27 + digits\x3B
 }

 // Group by 2 digits
 var out = \x27\x27\x3B
 for (var j = 0\x3B j \x3C digits.length\x3B j += 2) {
 if (out !== \x27\x27) out += \x27 \x27\x3B
 out += digits.substring(j\x2C j + 2)\x3B
 }

 console.log(\x27[TEL] OUT =\x27\x2C out)\x3B
 return out\x3B
}

script.description:
Format -\x3E Trim + remove spaces
ex : \x27 Le NédéLEC \x27 -\x3E \x27Le NédéLEC\x27

// Normalize spaces: trim + collapse multiple spaces
// BreezingForms safe (ES5)
// Gilles — 18/01/2026
// ---------------------------------------------------

script.code:
function gn_format_trimSpaces(str)
{
 return String(str || \x27\x27).replace(/\x5Cs+/g\x2C \x27 \x27).replace(/^\x5Cs+|\x5Cs+$/g\x2C \x27\x27)\x3B
}

script.description:
Format \x22 Ville \x22
Format FR\x2C ex.: Montigny-le-Bretonneux\x2C Les Essarts-le-Roi\x2C Saint-Cyr-l\x27École

// ------------------------------------------------------------
// Format French city names
//
// Rules:
// - Letters (with accents)\x2C spaces\x2C hyphens\x2C apostrophes
// - Remove digits \x26 symbols
// - Normalize spaces
// - Capitalize words and hyphenated parts
// - Debug: IN / OUT
//
// Joomla 6 / BreezingForms safe (ES5)
// Gilles — 18/01/2026

script.code:
function gn_format_ville(input)
{
 console.log(\x27[VILLE] IN =\x27\x2C input)\x3B

 var v = String(input || \x27\x27)\x3B

 // Remove digits
 v = v.replace(/[0-9]/g\x2C \x27\x27)\x3B

 // Remove unwanted symbols (keep letters\x2C space\x2C - and \x27)
 v = v.replace(/[^A-Za-zÀ-ÿ \x27\x5C-]/g\x2C \x27 \x27)\x3B

 // Normalize spaces
 v = v.replace(/\x5Cs+/g\x2C \x27 \x27).replace(/^\x5Cs+|\x5Cs+$/g\x2C \x27\x27)\x3B

 // Capitalize words + hyphenated parts
 v = v.toLowerCase().replace(/\x5Cb[a-zà-ÿ]/g\x2C function (c) {
 return c.toUpperCase()\x3B
 })\x3B

 console.log(\x27[VILLE] OUT =\x27\x2C v)\x3B
 return v\x3B
} // gn_format_ville

script.description:
Renvoi le Nom de l\x27élément BreezingForms
Reconstruit le nom logique BF\x2C 
quand on part d’un élément ou d\x27une action DOM (this)
// --------------------------------------
// Lit le Nom de l\x27élément 
// -\x3E Reconstruire le nom logique BF
// → quand on part d’un élément ou action DOM (this)
// Gilles — 18/01/2026
// --------------------------------------

script.code:
function gn_getBFElementName(element) 
{
 if (!element || !element.id) return \x27\x27\x3B

 for (var i = 0\x3B i \x3C ff_elements.length\x3B i++) {
 if (ff_elements[i][0] === element.id) {
