// 01/01/2025 - Gilles
// Note: bug fix + Add separatar \x27\x3B\x27 or/and \x27\x2C\x27
// Tested PHP 8.3\x2C Joomla 5.2

script.code:
function gn_setCheckboxList(name\x2C values\x2C checked = true) {
 // Si \x27values\x27 est une chaîne\x2C on la convertit en tableau en utilisant virgule et point-virgule comme séparateurs
 if (typeof values === \x27string\x27) {
 values = values.split(/[\x3B\x2C]\x5Cs*/)\x3B // Sépare sur \x27\x2C\x27 ou \x27\x3B\x27 et enlève les espaces après le séparateur
 }

 // Appliquer trim sur chaque valeur
 values = values.map(value =\x3E value.trim())\x3B

 for (var i = 0\x3B i \x3C ff_elements.length\x3B i++) {
 if (ff_elements[i][2] == name) {
 var e = ff_getElementByIndex(i)\x3B
 var checkboxes = document.getElementsByName(e.name)\x3B

 // Parcourt les cases à cocher pour définir uniquement celles dans \x27values\x27
 for (var checkbox of checkboxes) {
 // Appliquer trim à la valeur de la case à cocher avant de la comparer
 if (values.includes(checkbox.value.trim())) {
 checkbox.checked = checked\x3B // Définit uniquement les cases spécifiées
 }
 // Les autres cases ne sont pas modifiées
 }
 break\x3B // Une fois trouvé\x2C on sort
 }
 }
}

function gn_setChecked(name\x2C value\x2C checked) {
 if (arguments.length\x3C3) checked = true\x3B
 for (var i = 0\x3B i \x3C ff_elements.length\x3B i++) {
 if (ff_elements[i][2] == name) {
 var e = ff_getElementByIndex(i)\x3B
 radiobuttons = document.getElementsByName(e.name)\x3B
 for (var radiobutton of radiobuttons) {
 if (radiobutton.value == value) {
 radiobutton.checked = checked\x3B
 break\x3B
 } // if
 } // for
 } // if
 } // for
} // gn_setChecked

script.description:
// Select from List
gn_setSelected(\x27Categorie\x27\x2C \x27Route\x27)\x3B

// Checkbox group

// Gil - 12/1/2026
// gn_setSelected :
// Set ONE value on a BF Select from List (single)
gn_setSelected(\x27GroupesVcmb\x27\x2C \x27Route\x3BGravel\x27)\x3B
gn_setSelected(\x27GroupesVcmb\x27\x2C [\x27Route\x27\x2C\x27Gravel\x27]\x2C \x27only\x27)\x3B

script.code:
function gn_setSelected(name\x2C value) {
 value = (value ?? \x27\x27).toString().trim()\x3B

 for (var i = 0\x3B i \x3C ff_elements.length\x3B i++) {
 if (ff_elements[i][2] === name) {

 var e = ff_getElementByIndex(i)\x3B
 if (!e || !e.options) return false\x3B

 var found = false\x3B
 for (var o = 0\x3B o \x3C e.options.length\x3B o++) {
 if (String(e.options[o].value).trim() === value) {
 e.selectedIndex = o\x3B
 found = true\x3B
 break\x3B
 }
 }

 if (!found) {
 // si aucune option ne correspond\x2C on laisse la sélection actuelle
 // (ou e.selectedIndex = -1 si tu préfères)
 // console.warn(\x27Option not found for\x27\x2C name\x2C \x27value=\x27\x2C value)\x3B
 }

 e.dispatchEvent?.(new Event(\x27change\x27\x2C { bubbles: true }))\x3B
 return true\x3B
 }
 }
 return false\x3B
}

script.description:
// Select from List
