// - Select from List -\x3E set ONE value
// - Checkbox group -\x3E set multiple values (\x22a\x3Bb\x2Cc\x22 or [\x22a\x22\x2C\x22b\x22])
// mode for checkbox: \x22exact\x22 (default) = uncheck others\x2C \x22only\x22 = keep others
gn_setSelected(\x27GroupesVcmb\x27\x2C \x27Route\x3BGravel\x27)\x3B
