script.code:
function gn_setSelected_NEW(name\x2C value) {
 var el = ff_getElementByName(name)\x3B
 if (!el) return false\x3B

 for (var i = 0\x3B i \x3C el.options.length\x3B i++) {
 if (el.options[i].value == value) {
 el.options[i].selected = true\x3B
 return true\x3B
 }
 }
 return false\x3B

} // gn_setSelected

function gn_validate_page_fin(element\x2C action)
{
 if (typeof bfUseErrorAlerts != \x27undefined\x27){
 JQuery(\x22.bfErrorMessage\x22).html(\x27\x27)\x3B
 JQuery(\x22.bfErrorMessage\x22).css(\x22display\x22\x2C\x22none\x22)\x3B
 }

 error = ff_validation(ff_currentpage)\x3B
 if (error != \x27\x27) {
 if (typeof bfUseErrorAlerts == \x27undefined\x27){
 Swal.fire(error)\x3B
 } else {
 bfShowErrors(error)\x3B
 }
 ff_validationFocus(\x27\x27)\x3B
 } else {
 ff_switchpage(ff_lastpage-1)\x3B
 self.scrollTo(0\x2C0)\x3B 
 }
} // gn_validate_page_fin

function gn_validate_submit(element\x2C action)
{
 if (typeof bfUseErrorAlerts != \x27undefined\x27){
 JQuery(\x22.bfErrorMessage\x22).html(\x27\x27)\x3B
 JQuery(\x22.bfErrorMessage\x22).css(\x22display\x22\x2C\x22none\x22)\x3B
 }
 error = ff_validation(0)\x3B
 if (error != \x27\x27) {

 if (typeof bfUseErrorAlerts == \x27undefined\x27){
 alert(error)\x3B
 } else {
 bfShowErrors(error)\x3B
 }
 ff_validationFocus()\x3B
 } else {
 // Vérif SPAM si le NOM et PRENOM sont différents = OK
 nom = ff_getElementByName(\x22Nom\x22).value \x3B
 prenom = ff_getElementByName(\x22Prenom\x22).value \x3B
 
 // Minuscule\x2C puis enlève les espaces de Début et de Fin
 nom =nom.toLowerCase().trim() \x3B
 prenom = prenom.toLowerCase().trim() \x3B

 // SPAM si le Nom = Prénom ou si le Prénom commence par le Nom (Gil \x3E Gil-André)
 if ( prenom.search(nom) == 0 ){
 // Tentative de SPAM\x2C Sortie Page d\x27accueil Cyclo
 gn_annuler_cyclo() \x3B
 } else {
 // Nom et Prénom OK\x2C Submit Formulaire
 ff_submitForm() \x3B 
 }
 } 
} // gn_validate_submit

