function ff_databaseToSelect($st\x2C $tbl\x2C $lbl\x2C $val\x2C $sql)
{
 $db = BFFactory::getDBO()\x3B // Get Database Object
 global $ff_processor\x3B

 // Create your own query here
 if ($sql and $sql != \x27\x27){
 $db-\x3EsetQuery($sql)\x3B
 }else{
 $db-\x3EsetQuery(\x22SELECT $lbl\x2C $val FROM $tbl\x22)\x3B
 }
 

 try {
 $result = $db-\x3EloadObjectList()\x3B // Load the result from the query
 } catch (\x5CException $e) {
 Factory::getApplication()-\x3EenqueueMessage($e-\x3EgetMessage())\x2C \x27error\x27\x3B
 return\x3B
 )
 
 $values = []\x3B
 foreach($result as $rrow){
 $values[]=(object)array(\x27selected\x27=\x3E0\x2C \x27label\x27=\x3E$rrow-\x3E{$lbl}\x2C \x27value\x27=\x3E$rrow-\x3E{$val})\x3B
 }
 
 unset($rrow)\x3B
 
 foreach($ff_processor-\x3Erows as $row)
 {
 if ($row-\x3Ename==$st){
 $row-\x3EselectList = $values\x3B
 foreach($values as $var){
 $row-\x3Edata2 .= $var-\x3Eselected.\x22\x3B\x22.$var-\x3Elabel.\x22\x3B\x22.$var-\x3Evalue.\x22\x5Cn\x22\x3B
 }
 break\x3B
 }
 unset($row)\x3B
 }
}

