function ff_query($sql\x2C $insert=false\x2C $error=FF_DIE)
{
 global $ff_processor\x3B
 $database = BFFactory::getDBO()\x3B
 if ($ff_processor-\x3Edying \x26\x26 $error!=FF_IGNOREDIE) return -1\x3B
 $database-\x3EsetQuery($sql)\x3B

 try {
 $database-\x3Equery()\x3B
 $error = null\x3B
 if ($insert)
 return $database-\x3Einsertid()\x3B
 } catch (\x5CRuntimeException $e) {
 $dienow = $error==FF_DIE\x3B
 $error = $e-\x3EgetMessage()\x3B
 if ($dienow) ff_die($error)\x3B
 }
 
 return 0\x3B
} // ff_query

function ff_redirect($url\x2C $target=\x27self\x27\x2C $method=\x27post\x27)
{
 global $ff_processor\x2C $ff_request\x3B
 if ($ff_processor-\x3Edying) return\x3B
 ob_end_clean()\x3B //when debugging change this to ob_end_flush()\x3B
 switch (strtolower($method)) {
 case \x27get\x27: {
 switch (strtolower($target)) {
 case \x27top\x27 :
 case \x27parent\x27: break\x3B
 default : $target = \x27window\x27\x3B //window \x3E document\x2C because cross browser compat\x2C or so I read
 } // switch
 echo \x27\x3Cscript type=\x22text/javascript\x22\x3E\x27.nl().
 \x22onload=function() { \x22.$target.\x22.location.href=\x27\x22.$url.\x22\x27\x3B }\x22.nl().
 \x27\x3C/script\x3E\x27.nl().
 \x27\x3C/\x27 .\x27body\x3E\x27.nl()\x3B
 break\x3B
 } // url
 default: { // post
 $pos = strpos($url\x2C\x27?\x27)\x3B //find the location of \x27?\x27 after which get parameters usually start
 $ff_request = array()\x3B //create an array to set it later to hold get parameters in associative form
 if ($pos){ //if query parameters are supplied\x2C the whole action becomes http://whatever.com/
 $action=substr($url\x2C 0\x2C $pos)\x3B
 }else{ //if no \x27?\x27 detected action is equal to supplied url\x2C which is a weak check because what if pretty url?
 $action = $url\x3B
 }
 switch (strtolower($target)) {
 case \x27blank\x27 : $target = \x27 target=\x22_blank\x22\x27\x3B break\x3B
 case \x27top\x27 : $target = \x27 target=\x22_top\x22\x27\x3B break\x3B
 case \x27parent\x27: $target = \x27 target=\x22_parent\x22\x27\x3B break\x3B
 default : $target = \x27 target=\x22_self\x22\x27\x3B
 } // switch
 $parts = parse_url($url)\x3B //$url still stores are query params\x2C so we parse them
 parse_str($parts[\x27query\x27]\x2C $ff_request)\x3B //get query part and store into ff_request (defined above)
 echo \x27\x3Cscript language=\x22javascript\x22 type=\x22text/javascript\x22\x3E\x27.nl(). //echo form and script that submits form on load (ajax maybe\x2C more \x27elegant\x27?)
 \x27\x3C!--\x27.nl().
 \x27onload = function() { document.ff_redirect.submit()\x3B }\x27.nl().
 \x27--\x3E\x27.nl().
 \x27\x3C/script\x3E\x27.nl().
 \x27\x3Cform action=\x22\x27.$action.\x27\x22 \x27.
 \x27method=\x22post\x22 \x27.
 \x27name=\x22ff_redirect\x22 id=\x22ff_redirect\x22 \x27.
 \x27enctype=\x22multipart/form-data\x22\x27.
 $target.
 \x27\x3E\x27.nl()\x3B
 foreach ($ff_request as $key =\x3E $value){ //print out input fields which store GET parameters
 echo \x27\x3Cinput type=\x22hidden\x22 name=\x22\x27.$key.\x27\x22 \x27.\x27value=\x22\x27.htmlentities(urldecode($value)).\x27\x22/\x3E\x27.nl()\x3B
 }
 echo \x27\x3C/form\x3E\x27.nl(). \x27\x3C/\x27 .\x27body\x3E\x27.nl()\x3B
 } // post
 } // switch
 exit\x3B
} // ff_redirect

function ff_redirectForm($name\x2C $params=\x27\x27\x2C $method=\x27post\x27)
{
 $url=ff_makeFormUrl($name\x2C $params)\x3B
 ff_redirectParent($url\x2C $method)\x3B
} // ff_redirectForm

