function ff_setChecked($name\x2C $value)
{
 global $ff_processor\x3B
 for ($r = 0\x3B $r \x3C $ff_processor-\x3Erowcount\x3B $r++) {
 $row =\x26 $ff_processor-\x3Erows[$r]\x3B
 if ($row-\x3Ename==$name \x26\x26 $row-\x3Edata1==$value)
 $row-\x3Eflag1 = 1\x3B
 unset($row)\x3B
 } // for
} // ff_setChecked

function ff_setSelected($name\x2C $value)
{
 global $ff_processor\x3B
 for ($r = 0\x3B $r \x3C $ff_processor-\x3Erowcount\x3B $r++) {
 $row =\x26 $ff_processor-\x3Erows[$r]\x3B
 if ($row-\x3Ename==$name)
 $row-\x3Edata2 =
 preg_replace(
 \x27/(^|\x5Cr\x5Cn|\x5Cn)(0|1)\x3B([^\x3B]*)\x3B(\x27.$value.\x27)($|\x5Cr\x5Cn|\x5Cn)/\x27\x2C
 \x27${1}1\x3B${3}\x3B${4}${5}\x27\x2C
 $row-\x3Edata2
 )\x3B
 unset($row)\x3B
 } // for
} // ff_setSelected

function ff_setValue($name\x2C $value)
{
 global $ff_processor\x3B
 for ($r = 0\x3B $r \x3C $ff_processor-\x3Erowcount\x3B $r++) {
 $row =\x26 $ff_processor-\x3Erows[$r]\x3B
 if ($row-\x3Ename==$name)
 $row-\x3Edata1 = $value\x3B
 unset($row)\x3B
 } // for
} // ff_setValue

use Joomla\x5CCMS\x5CFactory\x3B
