/**
 * ------------------------------------------------
 * gn_countRecords($formName)
 * ------------------------------------------------
 * Compte le nombre d\x27enregistrements BF
 * pour un formulaire donné (par son nom)
 *
 * Retour :
 * - nombre d\x27enregistrements
 * - 0 si non trouvé / erreur
 * ------------------------------------------------
 */

function gn_countRecords($formName): int
{
 $GN_DEBUG = false\x3B

 $formName = trim((string) $formName)\x3B

 if ($formName === \x27\x27) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_countRecords: empty formName\x27)\x3B
 }
 return 0\x3B
 }

 try {
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27COUNT(1)\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_records\x27))
 -\x3Ewhere($db-\x3EquoteName(\x27name\x27) . \x27 = :formname\x27)
 -\x3Ebind(\x27:formname\x27\x2C $formName)\x3B

 $db-\x3EsetQuery($query)\x3B

 $count = (int) $db-\x3EloadResult()\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_countRecords: form=\x27 . $formName . \x27 count=\x27 . $count)\x3B
 }

 return $count\x3B

 } catch (\x5CThrowable $e) {

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_countRecords ERROR: \x27 . $e-\x3EgetMessage())\x3B
 }

 return 0\x3B
 }

} // gn_countRecords

