/**
 * ------------------------------------------------
 * gn_getDBField($name\x2C $recid)
 * ------------------------------------------------
 * Récupère la valeur d\x27un champ (name) pour un enregistrement
 * donné dans la table BF :
 * #__facileforms_subrecords
 *
 * Paramètres :
 * - $name : nom du champ BF (ex: \x22EMAIL\x22\x2C \x22NOM\x22\x2C etc.)
 * - $recid : ID de l\x27enregistrement (record)
 *
 * Fonctionnement :
 * - vérifie les paramètres (non vides)
 * - interroge la table subrecords
 * - retourne la valeur trouvée
 * - retourne \x27UNKNOWN\x27 si null ou vide
 *
 * Exemple :
 * gn_getDBField(\x27EMAIL\x27\x2C 123)
 * -\x3E \x22test@mail.com\x22
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */

function gn_getDBField($name\x2C $recid): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Vérifications des paramètres
 // ------------------------------------------------
 if ($name === null || $name === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: name\x27)\x3B
 }

 if ($recid === null || $recid === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: recid\x27)\x3B
 }

 // Typage sécurisé
 $recid = (int) $recid\x3B
 $name = trim((string) $name)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_getDBField: recid=\x27 . $recid . \x27 name=\x27 . $name)\x3B
 }

 // ------------------------------------------------
 // Accès base Joomla
 // ------------------------------------------------
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 // ------------------------------------------------
 // Construction requête
 // ------------------------------------------------
 $query = $db-\x3EgetQuery(true)
 -\x3Eselect($db-\x3EquoteName(\x27value\x27))
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_subrecords\x27))
 -\x3Ewhere($db-\x3EquoteName(\x27record\x27) . \x27 = :recid\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27name\x27) . \x27 = :name\x27)
 -\x3Ebind(\x27:recid\x27\x2C $recid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)
 -\x3Ebind(\x27:name\x27\x2C $name)
 -\x3EsetLimit(1)\x3B

 $db-\x3EsetQuery($query)\x3B

 // ------------------------------------------------
 // Exécution
 // ------------------------------------------------
 $value = $db-\x3EloadResult()\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_getDBField: result=\x27 . print_r($value\x2C true))\x3B
 }

 // ------------------------------------------------
 // Résultat
 // ------------------------------------------------
 return ($value === null || $value === \x27\x27) ? \x27UNKNOWN\x27 : (string) $value\x3B

} // gn_getDBField

