 * - recherche uniquement les formulaires publiés
 * - retourne le premier trouvé selon ordering puis id
 * - exception si introuvable
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_getFormFromFormName($formname = \x27SystemDashboard\x27): object
{
