 if ($formname === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: formname\x27)\x3B
 }

 // ------------------------------------------------
 // Accès base Joomla
 // ------------------------------------------------
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 // ------------------------------------------------
 // Construction requête
 // ------------------------------------------------
 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27*\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_forms\x27))
 -\x3Ewhere($db-\x3EquoteName(\x27name\x27) . \x27 = :formname\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27published\x27) . \x27 = :published\x27)
 -\x3Eorder($db-\x3EquoteName(\x27ordering\x27) . \x27 ASC\x2C \x27 . $db-\x3EquoteName(\x27id\x27) . \x27 ASC\x27)
 -\x3Ebind(\x27:formname\x27\x2C $formname\x2C ParameterType::STRING)
 -\x3Ebind(\x27:published\x27\x2C 1\x2C ParameterType::INTEGER)\x3B

 $db-\x3EsetQuery($query\x2C 0\x2C 1)\x3B

 $form = $db-\x3EloadObject()\x3B

 // ------------------------------------------------
 // Formulaire introuvable
 // ------------------------------------------------
 if (!$form) {
 throw new InvalidArgumentException(\x27Form not found: \x27 . $formname)\x3B
 }

 return $form\x3B

} // gn_getFormFromFormName

