/**
 * ------------------------------------------------
 * gn_getNbInscrit($formId\x2C $name\x2C $value)
 * ------------------------------------------------
 * Compte le nombre d\x27inscrits pour un formulaire BF
 * ayant une valeur donnée dans un champ donné.
 *
 * Exemple :
 * gn_getNbInscrit(12\x2C \x27PARCOURS\x27\x2C \x27100 km\x27)
 *
 * Fonctionnement :
 * - vérifie les paramètres
 * - joint #__facileforms_records et #__facileforms_subrecords
 * - filtre sur :
 * - l\x27ID du formulaire
 * - le nom du champ
 * - la valeur du champ
 * - retourne le nombre trouvé
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_getNbInscrit($formId\x2C $name\x2C $value): int
{
 // ------------------------------------------------
 // Vérifications des paramètres
 // ------------------------------------------------
 if ($formId === null || $formId === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: formId\x27)\x3B
 }

 if ($name === null || $name === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: name\x27)\x3B
 }

 if ($value === null || $value === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: value\x27)\x3B
 }

 // Typage sécurisé
 $formId = (int) $formId\x3B
 $name = trim((string) $name)\x3B
 $value = trim((string) $value)\x3B

 if ($formId \x3C= 0) {
 throw new InvalidArgumentException(\x27Invalid parameter: formId must be \x3E 0\x27)\x3B
 }

 // ------------------------------------------------
 // Accès base Joomla
 // ------------------------------------------------
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 // ------------------------------------------------
 // Requête principale
 // ------------------------------------------------
 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27COUNT(1)\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_subrecords\x27\x2C \x27s\x27))
 -\x3Ejoin(
 \x27INNER\x27\x2C
 $db-\x3EquoteName(\x27#__facileforms_records\x27\x2C \x27r\x27)
 . \x27 ON \x27 . $db-\x3EquoteName(\x27r.id\x27) . \x27 = \x27 . $db-\x3EquoteName(\x27s.record\x27)
 )
 -\x3Ewhere($db-\x3EquoteName(\x27r.form\x27) . \x27 = :formid\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27s.name\x27) . \x27 = :name\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27s.value\x27) . \x27 = :value\x27)
 -\x3Ebind(\x27:formid\x27\x2C $formId\x2C ParameterType::INTEGER)
 -\x3Ebind(\x27:name\x27\x2C $name\x2C ParameterType::STRING)
 -\x3Ebind(\x27:value\x27\x2C $value\x2C ParameterType::STRING)\x3B

 $db-\x3EsetQuery($query)\x3B

 return (int) $db-\x3EloadResult()\x3B

