piece.description:
Returns the next competitor number of a form 
* $form : the number of the current form.
* $field_dossard: the name of the element which contains the competitor number (FIELD_DOSSARD field)\x2C
* $first_dossard: the first competitor number to be assigned (FIRST_DOSSARD).

 // Principle: search in the database in the #__facileforms_subrecords table for the largest competitor number already assigned for this form.
 // The table #__facileforms_subrecords (list of each element value) has :
 // * a value text field containing the data\x2C
 // * a text field `name` containing the name of the element\x2C
 // \x22 an integer field record containing the id of the record ( record_id).

 // The table #__facileforms_records (list of records) has:
 // \x22 an integer field id containing the id of the record ( record_id).
 // * an integer field form containing the form number ( form_id
// Gilles — 24/03/2026

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CDatabase\x5CDatabaseInterface\x3B
use Joomla\x5CDatabase\x5CParameterType\x3B

/**
 * ------------------------------------------------
 * gn_getNextNumDossard($form\x2C $field_dossard\x2C $first_dossard)
 * ------------------------------------------------
 * Retourne le prochain numéro de dossard disponible
 * pour un formulaire BreezingForms.
 *
 * Principe :
 * - cherche la valeur maximale existante dans le champ
 * $field_dossard des enregistrements du formulaire $form
 * - si aucune valeur trouvée → démarre à $first_dossard
 * - retourne le numéro suivant
 *
 * Paramètres :
 * - $form : ID du formulaire BF
 * - $field_dossard : nom du champ contenant le dossard
 * - $first_dossard : premier numéro autorisé
 *
 * Exemple :
 * - dossards existants : 101\x2C 102\x2C 103
 * - first_dossard = 100
 * -\x3E retourne 104
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_getNextNumDossard($form\x2C $field_dossard\x2C $first_dossard): int
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Vérifications des paramètres
 // ------------------------------------------------
 if ($form === null || $form === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: form\x27)\x3B
 }

 if ($field_dossard === null || $field_dossard === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: field_dossard\x27)\x3B
 }

 if ($first_dossard === null || $first_dossard === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: first_dossard\x27)\x3B
 }

 $form = (int) $form\x3B
 $field_dossard = trim((string) $field_dossard)\x3B
 $first_dossard = (int) $first_dossard\x3B

 if ($form \x3C= 0) {
 throw new InvalidArgumentException(\x27Invalid parameter: form must be \x3E 0\x27)\x3B
 }

 if ($field_dossard === \x27\x27) {
 throw new InvalidArgumentException(\x27Invalid parameter: field_dossard\x27)\x3B
 }

 // ------------------------------------------------
 // Accès base Joomla
 // ------------------------------------------------
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 // ------------------------------------------------
 // Recherche du dossard max existant
 // CAST(value AS UNSIGNED) pour comparer en numérique
 // ------------------------------------------------
 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27MAX(CAST(\x27 . $db-\x3EquoteName(\x27s.value\x27) . \x27 AS UNSIGNED))\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_subrecords\x27\x2C \x27s\x27))
 -\x3Ejoin(
 \x27INNER\x27\x2C
 $db-\x3EquoteName(\x27#__facileforms_records\x27\x2C \x27r\x27)
 . \x27 ON \x27 . $db-\x3EquoteName(\x27r.id\x27) . \x27 = \x27 . $db-\x3EquoteName(\x27s.record\x27)
 )
 -\x3Ewhere($db-\x3EquoteName(\x27r.form\x27) . \x27 = :form\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27s.name\x27) . \x27 = :fieldname\x27)
 -\x3Ebind(\x27:form\x27\x2C $form\x2C ParameterType::INTEGER)
 -\x3Ebind(\x27:fieldname\x27\x2C $field_dossard\x2C ParameterType::STRING)\x3B

 $db-\x3EsetQuery($query)\x3B
 $dossard = $db-\x3EloadResult()\x3B

 if ($GN_DEBUG) {
 error_log(
 \x27[BF] gn_getNextNumDossard: form=\x27 . $form
 . \x27 field=\x27 . $field_dossard
 . \x27 first=\x27 . $first_dossard
 . \x27 max=\x27 . print_r($dossard\x2C true)
 )\x3B
 }

 // ------------------------------------------------
 // Sécurité :
 // - si aucune valeur trouvée
 // - ou si valeur \x3C premier dossard
 // alors on repart de (first_dossard - 1)
 // ------------------------------------------------
 $dossard = (int) $dossard\x3B

 if ($dossard \x3C $first_dossard) {
 $dossard = $first_dossard - 1\x3B
 }

 return $dossard + 1\x3B

} // gn_getNextNumDossard

