 // ------------------------------------------------
 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27*\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_elements\x27\x2C \x27e\x27))
 -\x3Ewhere($db-\x3EquoteName(\x27e.form\x27) . \x27 = :formid\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27e.published\x27) . \x27 = :published\x27)
 -\x3Ewhere($db-\x3EquoteName(\x27e.logging\x27) . \x27 = :logging\x27)
