 -\x3Ebind(\x27:formid\x27\x2C $formid\x2C ParameterType::INTEGER)
 -\x3Ebind(\x27:published\x27\x2C 1\x2C ParameterType::INTEGER)
 -\x3Ebind(\x27:logging\x27\x2C 1\x2C ParameterType::INTEGER)\x3B

 $db-\x3EsetQuery($query)\x3B

 $subforms = $db-\x3EloadObjectList()\x3B

 if (!is_array($subforms)) {
 $subforms = []\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_getSubFormsFromFormId: count=\x27 . count($subforms))\x3B
 }

 return $subforms\x3B

} // gn_getSubFormsFromFormId

use Joomla\x5CCMS\x5CFactory\x3B
