use Joomla\x5CCMS\x5CEnvironment\x5CBrowser\x3B

/**
 * ------------------------------------------------
 * gn_newRecord($form_name = \x27SystemDashboard\x27)
 * ------------------------------------------------
 * Crée un nouvel enregistrement BreezingForms dans
 * #__facileforms_records pour le formulaire donné.
 *
 * Fonctionnement :
 * - vérifie le nom du formulaire
 * - récupère le formulaire BF via gn_getFormFromFormName()
 * - prépare les métadonnées :
 * - date de soumission
 * - IP
 * - navigateur
 * - plateforme
 * - utilisateur Joomla si connecté
 * - insère l\x27enregistrement BF
 * - si ContentBuilder / ContentBuilderNG est présent
 * et lié au formulaire BF\x2C synchronise la table
 * #__contentbuilderng_records
 *
 * Retour :
 * - objet record créé
 * - exception si erreur critique
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_newRecord($form_name = \x27SystemDashboard\x27)
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Vérification paramètre
 // ------------------------------------------------
 $form_name = trim((string) $form_name)\x3B

 if ($form_name === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: form_name\x27)\x3B
 }

 // ------------------------------------------------
 // Initialisation contexte Joomla
 // ------------------------------------------------
 $app = Factory::getApplication()\x3B
 $jinput = $app-\x3Einput\x3B
 $database = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B
 $user = $app-\x3EgetIdentity()\x3B

 // IP client
 $ip = (string) $jinput-\x3Eserver-\x3Eget(\x27REMOTE_ADDR\x27\x2C \x27\x27)\x3B

 // Browser / plateforme
 $jbrowserInstance = Browser::getInstance()\x3B
 $browser = (string) $jbrowserInstance-\x3EgetAgentString()\x3B
 $platform = (string) $jbrowserInstance-\x3EgetPlatform()\x3B

 // Récupère le formulaire BF
 $form = gn_getFormFromFormName($form_name)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newRecord: form=\x27 . $form_name . \x27 formId=\x27 . $form-\x3Eid)\x3B
 }

 // ------------------------------------------------
 // Création de l\x27enregistrement BreezingForms
 // ------------------------------------------------
 $record = new facileFormsRecords($database)\x3B

 $record-\x3Esubmitted = Factory::getDate(\x27now\x27)-\x3Eformat(\x27Y-m-d H:i:s\x27\x2C true)\x3B
 $record-\x3Eform = (int) $form-\x3Eid\x3B
 $record-\x3Etitle = (string) $form-\x3Etitle\x3B
 $record-\x3Ename = (string) $form-\x3Ename\x3B
 $record-\x3Eip = $ip\x3B
 $record-\x3Ebrowser = $browser\x3B
 $record-\x3Eopsys = $platform\x3B
 $record-\x3Eprovider = \x27\x27\x3B
 $record-\x3Eviewed = 0\x3B
 $record-\x3Eexported = 0\x3B
 $record-\x3Earchived = 0\x3B

 // ------------------------------------------------
 // Infos utilisateur Joomla
 // ------------------------------------------------
 if ((int) $user-\x3Eget(\x27id\x27\x2C 0) \x3E 0) {
 $record-\x3Euser_id = (int) $user-\x3Eget(\x27id\x27\x2C 0)\x3B
 $record-\x3Eusername = (string) $user-\x3Eget(\x27username\x27\x2C \x27\x27)\x3B
 $record-\x3Euser_full_name = (string) $user-\x3Eget(\x27name\x27\x2C \x27\x27)\x3B
 } else {
 $record-\x3Euser_id = 0\x3B
 $record-\x3Eusername = \x27-\x27\x3B
 $record-\x3Euser_full_name = \x27-\x27\x3B
 }

 // ------------------------------------------------
 // Enregistrement BF
 // ------------------------------------------------
 if (!$record-\x3Estore()) {
 $msg = \x27[BF] gn_newRecord: store error: \x27 . $record-\x3EgetError()\x3B

 if ($GN_DEBUG) {
 error_log($msg)\x3B
 }

 throw new RuntimeException($msg)\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newRecord: record created id=\x27 . $record-\x3Eid)\x3B
 }

 // ------------------------------------------------
 // Synchronisation ContentBuilder / ContentBuilderNG
 // si un formulaire CB publié est lié à ce formulaire BF
 // ------------------------------------------------
 if (
 is_file(JPATH_ADMINISTRATOR . \x27/components/com_contentbuilderng/com_contentbuilderng.xml\x27)
 || is_file(JPATH_ADMINISTRATOR . \x27/components/com_contentbuilder/contentbuilder.xml\x27)
 ) {
 // Recherche du formulaire CB lié au formulaire BF
 $query = $database-\x3EgetQuery(true)
 -\x3Eselect($database-\x3EquoteName(\x27id\x27))
 -\x3Efrom($database-\x3EquoteName(\x27#__contentbuilderng_forms\x27))
 -\x3Ewhere($database-\x3EquoteName(\x27type\x27) . \x27 = \x27 . $database-\x3Equote(\x27com_breezingformsng\x27))
 -\x3Ewhere($database-\x3EquoteName(\x27reference_id\x27) . \x27 = :refid\x27)
 -\x3Ewhere($database-\x3EquoteName(\x27published\x27) . \x27 = 1\x27)
 -\x3Ebind(\x27:refid\x27\x2C $form-\x3Eid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)\x3B

 $database-\x3EsetQuery($query)\x3B
 $cbFormId = $database-\x3EloadResult()\x3B

 if ($cbFormId) {

 $last_update = Factory::getDate()-\x3EtoSql()\x3B

 // Vérifie si le lien record BF \x3C-\x3E CB existe déjà
 $query = $database-\x3EgetQuery(true)
 -\x3Eselect($database-\x3EquoteName(\x27id\x27))
 -\x3Efrom($database-\x3EquoteName(\x27#__contentbuilderng_records\x27))
 -\x3Ewhere($database-\x3EquoteName(\x27type\x27) . \x27 = \x27 . $database-\x3Equote(\x27com_breezingformsng\x27))
 -\x3Ewhere($database-\x3EquoteName(\x27reference_id\x27) . \x27 = :refid\x27)
 -\x3Ewhere($database-\x3EquoteName(\x27record_id\x27) . \x27 = :recordid\x27)
 -\x3Ebind(\x27:refid\x27\x2C $form-\x3Eid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)
 -\x3Ebind(\x27:recordid\x27\x2C $record-\x3Eid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)\x3B

 $database-\x3EsetQuery($query)\x3B
 $cbRecordLinkId = $database-\x3EloadResult()\x3B

 if (!$cbRecordLinkId) {
 // Insertion du lien CB
 $columns = [
 \x27session_id\x27\x2C
 \x27type\x27\x2C
 \x27last_update\x27\x2C
 \x27published\x27\x2C
 \x27record_id\x27\x2C
 \x27reference_id\x27\x2C
 ]\x3B

 $values = [
 $database-\x3Equote($app-\x3EgetSession()-\x3EgetId())\x2C
 $database-\x3Equote(\x27com_breezingformsng\x27)\x2C
 $database-\x3Equote($last_update)\x2C
 0\x2C
 (int) $record-\x3Eid\x2C
 (int) $form-\x3Eid\x2C
 ]\x3B

 $query = $database-\x3EgetQuery(true)
 -\x3Einsert($database-\x3EquoteName(\x27#__contentbuilderng_records\x27))
 -\x3Ecolumns(array_map([$database\x2C \x27quoteName\x27]\x2C $columns))
 -\x3Evalues(implode(\x27\x2C\x27\x2C $values))\x3B

 $database-\x3EsetQuery($query)\x3B
 $database-\x3Eexecute()\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newRecord: CB link inserted for record=\x27 . $record-\x3Eid)\x3B
 }

 } else {
 // Mise à jour du lien existant
 $query = $database-\x3EgetQuery(true)
 -\x3Eupdate($database-\x3EquoteName(\x27#__contentbuilderng_records\x27))
 -\x3Eset($database-\x3EquoteName(\x27last_update\x27) . \x27 = \x27 . $database-\x3Equote($last_update))
 -\x3Eset($database-\x3EquoteName(\x27edited\x27) . \x27 = \x27 . $database-\x3EquoteName(\x27edited\x27) . \x27 + 1\x27)
 -\x3Ewhere($database-\x3EquoteName(\x27type\x27) . \x27 = \x27 . $database-\x3Equote(\x27com_breezingformsng\x27))
 -\x3Ewhere($database-\x3EquoteName(\x27reference_id\x27) . \x27 = :refid\x27)
 -\x3Ewhere($database-\x3EquoteName(\x27record_id\x27) . \x27 = :recordid\x27)
 -\x3Ebind(\x27:refid\x27\x2C $form-\x3Eid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)
 -\x3Ebind(\x27:recordid\x27\x2C $record-\x3Eid\x2C \x5CJoomla\x5CDatabase\x5CParameterType::INTEGER)\x3B

 $database-\x3EsetQuery($query)\x3B
 $database-\x3Eexecute()\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newRecord: CB link updated for record=\x27 . $record-\x3Eid)\x3B
 }
 }
 }
 }

 return $record\x3B

} // gn_newRecord

use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CDatabase\x5CDatabaseInterface\x3B

/**
 * ------------------------------------------------
 * gn_newSubRecord($record\x2C $name\x2C $value)
 * ------------------------------------------------
 * Crée un sous-enregistrement BreezingForms dans
 * #__facileforms_subrecords pour un record donné.
 *
 * Fonctionnement :
 * - vérifie les paramètres
 * - récupère les éléments publiés/loggés du formulaire
 * - cherche l\x27élément correspondant au nom $name
 * - crée un subrecord avec :
 * - record = id du record parent
 * - element = id de l\x27élément BF
 * - name = nom de l\x27élément
 * - type = type BF
 * - value = valeur à stocker
 *
 * Retour :
 * - true si insertion OK
 * - false si élément non trouvé ou store KO
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_newSubRecord($record\x2C $name\x2C $value): bool
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Vérifications des paramètres
 // ------------------------------------------------
 if ($record === null || $record === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: record\x27)\x3B
 }

 if (!is_object($record) || !isset($record-\x3Eid) || !isset($record-\x3Eform)) {
 throw new InvalidArgumentException(\x27Invalid parameter: record must be an object with id and form\x27)\x3B
 }

 if ($name === null || $name === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: name\x27)\x3B
 }

 if ($value === null || $value === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: value\x27)\x3B
 }

 $name = trim((string) $name)\x3B
 $value = (string) $value\x3B

 if ($GN_DEBUG) {
 error_log(
 \x27[BF] gn_newSubRecord: recordId=\x27 . $record-\x3Eid .
 \x27 formId=\x27 . $record-\x3Eform .
 \x27 name=\x27 . $name .
 \x27 value=\x27 . $value
 )\x3B
 }

 // ------------------------------------------------
 // Récupère les éléments BF du formulaire
 // ------------------------------------------------
 $subrecords = gn_getSubFormsFromFormId((int) $record-\x3Eform)\x3B

 foreach ($subrecords as $sr) {

 if ($sr-\x3Ename == $name) {

 $database = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 $subrecord = new facileFormsSubrecords($database)\x3B

 // ID auto
 $subrecord-\x3Erecord = (int) $record-\x3Eid\x3B // record parent
 $subrecord-\x3Eelement = (int) $sr-\x3Eid\x3B // element BF
 $subrecord-\x3Ename = (string) $sr-\x3Ename\x3B
 $subrecord-\x3Etype = (string) $sr-\x3Etype\x3B
 $subrecord-\x3Evalue = $value\x3B

 if (!$subrecord-\x3Estore()) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newSubRecord: store failed for name=\x27 . $name)\x3B
 }
 return false\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newSubRecord: subrecord created for name=\x27 . $name)\x3B
 }

 return true\x3B
 }
 }

 // ------------------------------------------------
 // Élément BF non trouvé
 // ------------------------------------------------
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_newSubRecord: field not found in form for name=\x27 . $name)\x3B
 }

 return false\x3B

} // gn_newSubRecord

/**
 * ------------------------------------------------
 * gn_setMemoryData(\x26$that\x2C $element\x2C $value)
 * ------------------------------------------------
 * Met à jour une valeur dans les structures BF :
 * - maildata (emails)
 * - savedata (base de données)
 *
 * Fonctionnement :
 * - cherche l\x27élément par son nom
 * - met à jour la valeur dans les deux tableaux
 *
 * Paramètres :
 * - $that : objet BreezingForms (contexte form)
 * - $element : nom du champ
 * - $value : valeur à affecter
 *
 * Retour :
 * - true si au moins une mise à jour effectuée
 * - false sinon
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_setMemoryData(\x26$that\x2C $element\x2C $value): bool
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Vérifications
 // ------------------------------------------------
 if ($that === null || !is_object($that)) {
 throw new InvalidArgumentException(\x27Invalid parameter: that must be an object\x27)\x3B
 }

 if ($element === null || $element === \x27\x27) {
 throw new InvalidArgumentException(\x27Missing or empty parameter: element\x27)\x3B
 }

 if ($value === null) {
 throw new InvalidArgumentException(\x27Missing parameter: value\x27)\x3B
 }

 $element = (string) $element\x3B
 $value = (string) $value\x3B

 // Vérifie constantes BF
 if (!defined(\x27_FF_DATA_NAME\x27) || !defined(\x27_FF_DATA_VALUE\x27)) {
 throw new RuntimeException(\x27BF constants not defined\x27)\x3B
 }

 $updated = false\x3B

 // ------------------------------------------------
 // Mise à jour maildata (email)
 // ------------------------------------------------
 if (isset($that-\x3Emaildata) \x26\x26 is_array($that-\x3Emaildata)) {

 foreach ($that-\x3Emaildata as \x26$entry) {

 if (isset($entry[_FF_DATA_NAME]) \x26\x26 $entry[_FF_DATA_NAME] == $element) {
 $entry[_FF_DATA_VALUE] = $value\x3B
 $updated = true\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_setMemoryData: maildata updated \x27 . $element)\x3B
 }

 break\x3B
 }
 }
 }

 // ------------------------------------------------
 // Mise à jour savedata (DB)
 // ------------------------------------------------
 if (isset($that-\x3Esavedata) \x26\x26 is_array($that-\x3Esavedata)) {

 foreach ($that-\x3Esavedata as \x26$entry) {

 if (isset($entry[_FF_DATA_NAME]) \x26\x26 $entry[_FF_DATA_NAME] == $element) {
 $entry[_FF_DATA_VALUE] = $value\x3B
 $updated = true\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_setMemoryData: savedata updated \x27 . $element)\x3B
 }

 break\x3B
 }
 }
 }

 // ------------------------------------------------
 // Résultat
 // ------------------------------------------------
 if ($GN_DEBUG \x26\x26 !$updated) {
 error_log(\x27[BF] gn_setMemoryData: element not found \x27 . $element)\x3B
 }

 return $updated\x3B

} // gn_setMemoryData

function gn_validate_submit(element\x2C action)
{
 // ------------------------------------------------
 // Nettoyage des messages BF si le mode inline est actif
 // ------------------------------------------------
 if (typeof bfUseErrorAlerts !== \x27undefined\x27) {
 JQuery(\x22.bfErrorMessage\x22).html(\x27\x27)\x3B
 JQuery(\x22.bfErrorMessage\x22).css(\x22display\x22\x2C \x22none\x22)\x3B
 }

 // ------------------------------------------------
 // Validation standard BreezingForms
 // ------------------------------------------------
 var error = ff_validation(0)\x3B

 if (error !== \x27\x27) {

 // Affichage des erreurs
 if (typeof bfUseErrorAlerts === \x27undefined\x27) {
 alert(error)\x3B
 } else {
 bfShowErrors(error)\x3B
 }

 ff_validationFocus()\x3B
 return\x3B
 }

 // ------------------------------------------------
 // Contrôle anti-spam simple :
 // - NOM et PRENOM ne doivent pas être identiques
 // - le prénom ne doit pas commencer par le nom
 // ex : nom = \x22gil\x22\x2C prénom = \x22gil-andré\x22
 // ------------------------------------------------
 var elNom = ff_getElementByName(\x22Nom\x22)\x3B
 var elPrenom = ff_getElementByName(\x22Prenom\x22)\x3B

 // Sécurité : si un champ est absent\x2C on soumet quand même
 if (!elNom || !elPrenom) {
 ff_submitForm()\x3B
 return\x3B
 }

 var nom = String(elNom.value || \x27\x27).toLowerCase().trim()\x3B
 var prenom = String(elPrenom.value || \x27\x27).toLowerCase().trim()\x3B

 // Sécurité : si l\x27un des champs est vide\x2C on laisse BF gérer
 if (nom === \x27\x27 || prenom === \x27\x27) {
 ff_submitForm()\x3B
 return\x3B
 }

 // SPAM si prénom = nom
 // ou si prénom commence par nom
 if (prenom.indexOf(nom) === 0) {
 // Tentative de spam -\x3E retour accueil
 gn_annuler_cyclo()\x3B
 return\x3B
 }

 // ------------------------------------------------
 // Contrôle OK -\x3E soumission du formulaire
 // ------------------------------------------------
 ff_submitForm()\x3B

} // gn_validate_submit

piece.description:
Extrait les \x22Activites VCMB\x22 du User Custom Field courant :
(Mercredicienne\x3B Jeudicienne\x2C ...)

// Gilles - 24/03/2026
// Get Joomla user custom field \x22activites\x22 (type: checkboxes)
// Return values joined with \x27\x3B\x27 (VCMB format) e.g. \x22Route\x3BGravel\x3BEcole jeunes\x22
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CComponent\x5CFields\x5CAdministrator\x5CHelper\x5CFieldsHelper\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_activites($fieldName = \x27activites\x27)
 * ------------------------------------------------
 * Lit un champ utilisateur personnalisé Joomla
 * de type \x22checkboxes\x22 (activités pratiquées)
 *
 * Exemple :
 * [\x22ROUTE\x22\x2C \x22GRAVEL\x22\x2C \x22VTT\x22]
 * -\x3E \x22ROUTE\x3BGRAVEL\x3BVTT\x22
 *
 * Fonctionnement :
 * - si utilisateur non connecté → retourne \x27\x27
 * - lit les champs custom utilisateur Joomla
 * - cherche le champ demandé
 * - vérifie qu\x27il est bien de type \x22checkboxes\x22
 * - si tableau → concatène avec \x27\x3B\x27
 * - fallback si string
 * - si champ non trouvé → retourne \x27\x27
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */

function gn_get_vcmb_activites($fieldName = \x27activites\x27): string
{
 $GN_DEBUG = false\x3B

 // Type attendu du champ
 $fieldType = \x27checkboxes\x27\x3B

 // ------------------------------------------------
 // Utilisateur courant
 // ------------------------------------------------
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eget(\x27id\x27) === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_activites: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // Récupération des champs personnalisés utilisateur
 // ------------------------------------------------
 $fields = FieldsHelper::getFields(\x27com_users.user\x27\x2C $user\x2C true)\x3B

 // ------------------------------------------------
 // Recherche du champ demandé
 // ------------------------------------------------
 foreach ($fields as $field) {

 if ($field-\x3Ename === $fieldName \x26\x26 $field-\x3Etype === $fieldType) {

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_activites: field found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 // Cas normal : checkboxes = tableau
 if (is_array($field-\x3Erawvalue)) {
 $vals = array_map(\x27trim\x27\x2C $field-\x3Erawvalue)\x3B
 return implode(\x27\x3B\x27\x2C $vals)\x3B
 }

 // Cas fallback (rare)
 return trim((string) $field-\x3Erawvalue)\x3B
 }
 }

 // ------------------------------------------------
 // Champ non trouvé
 // ------------------------------------------------
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_activites: field not found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 return \x27\x27\x3B

} // gn_get_vcmb_activites

piece.description:
Extrait \x22Adresse\x22 du Joomla User Profile VCMB (address1)
1ère ligne d\x27adresse

// Gilles - 24/03/2026
// Get Joomla PROFILE field \x22address1\x22 (profile.address1)
// Not a Joomla custom field (UF) -\x3E do NOT use FieldsHelper here
// Return empty string if not logged in or field not found
// Apply VCMB normalization (rue\x2C avenue\x2C de\x2C des\x2C etc -\x3E lower case)
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CCMS\x5CUser\x5CUserHelper\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_adresse($address = \x27\x27)
 * ------------------------------------------------
 * Retourne l\x27adresse postale d\x27un utilisateur Joomla.
 *
 * Fonctionnement :
 * - si $address est fourni → normalise cette valeur
 * - sinon → lit le champ profil Joomla \x22address1\x22
 * - si utilisateur non connecté → retourne \x27\x27
 * - si champ introuvable → retourne \x27\x27
 * - applique une normalisation simple \x22VCMB\x22
 *
 * Exemple :
 * \x2212 RUE DE LA PAIX\x22 -\x3E \x2212 rue de la Paix\x22
 * \x228 AVENUE DU GENERAL DE GAULLE\x22 -\x3E \x228 avenue du General de Gaulle\x22
 *
 * Compatible Joomla 6 / PHP 8.x / BreezingForms
 * ------------------------------------------------
 */
function gn_get_vcmb_adresse($address = \x27\x27): string
{
 $GN_DEBUG = false\x3B

 // Champ profil Joomla ciblé
 $profileField = \x27address1\x27\x3B

 // ------------------------------------------------
 // Si aucune adresse fournie → lecture du profil Joomla
 // ------------------------------------------------
 if ($address === null || trim((string) $address) === \x27\x27) {

 // Utilisateur courant
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_adresse: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 // Charge le profil de l\x27utilisateur
 $profile = UserHelper::getProfile((int) $user-\x3Eid)\x3B

 // Vérifie la présence du tableau de profil et du champ demandé
 if (
 !isset($profile-\x3Eprofile) ||
 !is_array($profile-\x3Eprofile) ||
 !array_key_exists($profileField\x2C $profile-\x3Eprofile)
 ) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_adresse: profile field not found [\x27 . $profileField . \x27]\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $address = (string) $profile-\x3Eprofile[$profileField]\x3B
 }

 // ------------------------------------------------
 // Nettoyage de base
 // ------------------------------------------------
 $addr = trim((string) $address)\x3B

 if ($addr === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_adresse: raw=\x27 . $addr)\x3B
 }

 // ------------------------------------------------
 // Normalisation VCMB
 // ------------------------------------------------
 $addr = gn_get_vcmb_normalize_adresse($addr)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_adresse: normalized=\x27 . $addr)\x3B
 }

 return $addr\x3B

} // gn_get_vcmb_adresse


/**
 * ------------------------------------------------
 * gn_get_vcmb_normalize_adresse($s)
 * ------------------------------------------------
 * Normalise une adresse postale simple.
 *
 * Règles :
 * - trim
 * - passage global en \x22Title Case\x22
 * - certains mots usuels forcés en minuscule :
 * rue\x2C avenue\x2C boulevard\x2C impasse\x2C chemin\x2C de\x2C du\x2C des...
 *
 * Exemples :
 * \x2212 RUE DE LA PAIX\x22 -\x3E \x2212 rue de la Paix\x22
 * \x225 BOULEVARD DU ROI\x22 -\x3E \x225 boulevard du Roi\x22
 *
 * Remarque :
 * cette fonction reste volontairement simple
 * et ne prétend pas couvrir tous les cas postaux français.
 * ------------------------------------------------
 */
function gn_get_vcmb_normalize_adresse($s): string
{
 $s = trim((string) $s)\x3B

 if ($s === \x27\x27) {
 return \x27\x27\x3B
 }

 // Mise en forme générale
 $s = mb_convert_case($s\x2C MB_CASE_TITLE\x2C \x27UTF-8\x27)\x3B

 // Mots forcés en minuscule
 $lower = [
 \x27Rue\x27\x2C \x27Avenue\x27\x2C \x27Allée\x27\x2C \x27Boulevard\x27\x2C \x27Impasse\x27\x2C \x27Chemin\x27\x2C
 \x27Parc\x27\x2C \x27Square\x27\x2C \x27Résidence\x27\x2C \x27Lotissement\x27\x2C
 \x27De\x27\x2C \x27Du\x27\x2C \x27Des\x27\x2C \x27La\x27\x2C \x27Le\x27\x2C \x27Les\x27\x2C \x27Aux\x27\x2C \x27Au\x27\x2C \x27Et\x27
 ]\x3B

 foreach ($lower as $w) {
 $s = preg_replace(
 \x27/\x5Cb\x27 . preg_quote($w\x2C \x27/\x27) . \x27\x5Cb/u\x27\x2C
 mb_strtolower($w\x2C \x27UTF-8\x27)\x2C
 $s
 )\x3B
 }

 return $s\x3B

} // gn_get_vcmb_normalize_adresse

piece.description:
Extrait la \x22Civilité VCMB\x22 du User Custom Field Joomla courant
\x22Homme\x3B Femme\x3B Autre\x22

// Gilles - 24/03/2026
// Get Joomla user custom field \x22civilite\x22 (type: checkboxes)
// Return values joined with \x27\x3B\x27 (VCMB format) e.g. \x22Homme\x3B Femme\x3B Autre\x22
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CComponent\x5CFields\x5CAdministrator\x5CHelper\x5CFieldsHelper\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_civilite($fieldName = \x27civilite\x27)
 * ------------------------------------------------
 * Lit un champ utilisateur Joomla de type \x22radio\x22
 * (civilité : M\x2C Mme\x2C etc.)
 *
 * Exemple :
 * \x22M\x22
 * \x22Mme\x22
 *
 * Fonctionnement :
 * - si utilisateur non connecté → retourne \x27\x27
 * - lit les champs custom utilisateur Joomla
 * - cherche le champ demandé
 * - vérifie type \x22radio\x22
 * - retourne la valeur sélectionnée
 * - fallback si tableau (cas très rare)
 * - si champ non trouvé → retourne \x27\x27
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */

function gn_get_vcmb_civilite($fieldName = \x27civilite\x27): string
{
 $GN_DEBUG = false\x3B

 // Type attendu
 $fieldType = \x27radio\x27\x3B

 // ------------------------------------------------
 // Utilisateur courant
 // ------------------------------------------------
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eget(\x27id\x27) === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_civilite: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // Récupération des champs personnalisés utilisateur
 // ------------------------------------------------
 $fields = FieldsHelper::getFields(\x27com_users.user\x27\x2C $user\x2C true)\x3B

 // ------------------------------------------------
 // Recherche du champ
 // ------------------------------------------------
 foreach ($fields as $field) {

 if ($field-\x3Ename === $fieldName \x26\x26 $field-\x3Etype === $fieldType) {

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_civilite: field found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 // Cas normal : radio = string
 if (!is_array($field-\x3Erawvalue)) {
 return trim((string) $field-\x3Erawvalue)\x3B
 }

 // Fallback sécurité (rare)
 $vals = array_map(\x27trim\x27\x2C $field-\x3Erawvalue)\x3B
 return implode(\x27\x3B\x27\x2C $vals)\x3B
 }
 }

 // ------------------------------------------------
 // Champ non trouvé
 // ------------------------------------------------
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_civilite: field not found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 return \x27\x27\x3B

} // gn_get_vcmb_civilite

piece.description:
Extrait le Nom du \x22Club VCMB\x22 du User Custom Field Joomla courant
Exemple : \x22V.C. MONTIGNY-LE-BRETONNEUX\x22

// Extrait (\x22vcmb-club\x22) (type: text) de l\x27utilisateur courant
// Compatible Joomla 6 / PHP 8.x / BreezingForms
// Gilles - 24/03/2026

piece.code:
/**
 * ------------------------------------------------
 * gn_get_vcmb_club($fieldName = \x27vcmb-club\x27)
 * ------------------------------------------------
 * Récupère le nom du club depuis un champ utilisateur
 * personnalisé Joomla (Custom User Field).
 *
 * Fonctionnement :
 * - si aucun utilisateur connecté → retourne \x27\x27
 * - lit les champs custom utilisateur Joomla
 * - cherche le champ correspondant au nom fourni
 * - retourne sa valeur :
 * - rawvalue en priorité (valeur brute)
 * - sinon value (valeur formatée Joomla)
 * - gère les cas tableau (checkbox\x2C multi-valeurs)
 * - retourne \x27\x27 si champ non trouvé
 *
 * Paramètre :
 * - $fieldName : nom technique du champ Joomla
 * (ex: \x27vcmb-club\x27)
 *
 * Retour :
 * - string : valeur du champ (nom du club)
 * ------------------------------------------------
 */
function gn_get_vcmb_club($fieldName = \x27vcmb-club\x27): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Utilisateur courant Joomla
 // ------------------------------------------------
 $user = \x5CJoomla\x5CCMS\x5CFactory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_club: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // Lecture des champs personnalisés utilisateur
 // ------------------------------------------------
 $fields = \x5CJoomla\x5CComponent\x5CFields\x5CAdministrator\x5CHelper\x5CFieldsHelper::getFields(\x27com_users.user\x27\x2C $user\x2C true)\x3B

 // ------------------------------------------------
 // Parcours des champs pour trouver celui demandé
 // ------------------------------------------------
 foreach ($fields as $field) {

 if (($field-\x3Ename ?? \x27\x27) === $fieldName) {

 // ------------------------------------------------
 // Récupération de la valeur :
 // priorité à rawvalue (valeur brute DB)
 // sinon fallback sur value (valeur Joomla formatée)
 // ------------------------------------------------
 $value = $field-\x3Erawvalue ?? $field-\x3Evalue ?? \x27\x27\x3B

 // ------------------------------------------------
 // Gestion des champs multiples (checkbox\x2C etc.)
 // ------------------------------------------------
 if (is_array($value)) {
 $value = implode(\x27\x3B\x27\x2C array_map(\x27trim\x27\x2C $value))\x3B
 } else {
 $value = trim((string) $value)\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_club: field found [\x27 . $fieldName . \x27] value=\x27 . $value)\x3B
 }

 return $value\x3B
 }
 }

 // ------------------------------------------------
 // Champ non trouvé
 // ------------------------------------------------
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_club: field not found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 return \x27\x27\x3B

} // gn_get_vcmb_club

piece.description:
Extrait \x22Code Postal\x22 du Joomla User Profile VCMB (address1)

// Gilles - 24/03/2026
// Get Joomla PROFILE field \x22postal_code\x22 (profile.postal_code)
// Not a Joomla custom field (UF) -\x3E do NOT use FieldsHelper here
// Return empty string if not logged in or field not found
// VCMB normalization: digits only (keep 0-9)
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CCMS\x5CUser\x5CUserHelper\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_code_postal($postal_code = \x27\x27)
 * ------------------------------------------------
 * Retourne le code postal utilisateur Joomla
 *
 * Fonctionnement :
 * - si $postal_code fourni → normalise cette valeur
 * - sinon → lit le champ profil \x22postal_code\x22
 * - si utilisateur non connecté → retourne \x27\x27
 * - supprime tout sauf les chiffres
 *
 * Exemple :
 * \x2278 180\x22 -\x3E \x2278180\x22
 * \x2278180\x22 -\x3E \x2278180\x22
 * \x22FR-78180\x22 -\x3E \x2278180\x22
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */

function gn_get_vcmb_code_postal($postal_code = \x27\x27): string
{
 $GN_DEBUG = false\x3B

 // Champ profil Joomla
 $profileField = \x27postal_code\x27\x3B

 // ------------------------------------------------
 // Si vide → lecture profil utilisateur
 // ------------------------------------------------
 if ($postal_code === null || trim((string) $postal_code) === \x27\x27) {

 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_code_postal: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $profile = UserHelper::getProfile((int) $user-\x3Eid)\x3B

 if (
 !isset($profile-\x3Eprofile) ||
 !is_array($profile-\x3Eprofile) ||
 !array_key_exists($profileField\x2C $profile-\x3Eprofile)
 ) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_code_postal: profile field not found [\x27 . $profileField . \x27]\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $postal_code = (string) $profile-\x3Eprofile[$profileField]\x3B
 }

 // ------------------------------------------------
 // Nettoyage
 // ------------------------------------------------
 $cp = trim((string) $postal_code)\x3B

 if ($cp === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_code_postal: raw=\x27 . $cp)\x3B
 }

 // Conserve uniquement les chiffres
 $cp = preg_replace(\x27/\x5CD+/\x27\x2C \x27\x27\x2C $cp)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_code_postal: normalized=\x27 . $cp)\x3B
 }

 return $cp\x3B

} // gn_get_vcmb_code_postal

piece.description:
Lit la date pour la Timezone de Paris
Format date : JJ/MM/AAAA HH:MM

// Gilles — 24/03/2026
// Get local date (FR)
// Format : JJ/MM/AAAA HH:MM
// Timezone : Europe/Paris
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_date()
 * ------------------------------------------------
 * Returns current date/time using Joomla timezone
 * with optional inline debug output.
 *
 * Format:
 * DD/MM/YYYY HH:MM
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */
function gn_get_vcmb_date(): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Récupération timezone Joomla
 // ------------------------------------------------
 $config = Factory::getApplication()-\x3EgetConfig()\x3B
 $timezoneString = (string) $config-\x3Eget(\x27offset\x27\x2C \x27UTC\x27)\x3B

 try {
 $tz = new \x5CDateTimeZone($timezoneString)\x3B
 } catch (\x5CException $e) {
 $tz = new \x5CDateTimeZone(\x27UTC\x27)\x3B
 }

 // ------------------------------------------------
 // Date Joomla
 // ------------------------------------------------
 $date = Factory::getDate()-\x3EsetTimezone($tz)\x3B

 $out = $date-\x3Eformat(\x27d/m/Y H:i\x27\x2C true)\x3B

 // ------------------------------------------------
 // DEBUG (affichage inline)
 // ------------------------------------------------
 if ($GN_DEBUG) {
 return $out
 . \x27 | TZ=\x27 . $tz-\x3EgetName()
 . \x27 | offset=\x27 . $date-\x3Eformat(\x27P\x27)
 . \x27 | raw=\x27 . Factory::getDate()-\x3Eformat(\x27c\x27)\x3B
 }

 return $out\x3B

} // gn_get_vcmb_date

piece.description:
Extrait \x22Date de naissance\x22 du Joomla User Profile VCMB (dob)

// Gilles - 24/03/2026
// Get Joomla PROFILE field \x22dob\x22 (profile.dob)
// Not a Joomla custom field (UF) -\x3E do NOT use FieldsHelper here
// Return empty string if not logged in or field not found
// VCMB normalization: French date format \x2216/10/2003\x22 (date only\x2C no time)
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CCMS\x5CUser\x5CUserHelper\x3B

/**
 * Retourne la date de naissance au format FR : DD/MM/YYYY
 */
function gn_get_vcmb_date_naissance($birthdate = \x27\x27): string
{
 $GN_DEBUG = false\x3B
 $profileField = \x27dob\x27\x3B

 // Si aucune valeur passée -\x3E lecture du profil Joomla
 if ($birthdate === null || trim((string) $birthdate) === \x27\x27) {
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_date_naissance: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $profile = UserHelper::getProfile((int) $user-\x3Eid)\x3B

 if (
 !isset($profile-\x3Eprofile) ||
 !is_array($profile-\x3Eprofile) ||
 !array_key_exists($profileField\x2C $profile-\x3Eprofile)
 ) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_date_naissance: profile field not found [\x27 . $profileField . \x27]\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $birthdate = (string) $profile-\x3Eprofile[$profileField]\x3B
 }

 $raw = trim((string) $birthdate)\x3B

 if ($raw === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_date_naissance: raw=\x27 . $raw)\x3B
 }

 // 1) Cas ISO ou ISO + heure : YYYY-MM-DD...
 if (preg_match(\x27/^(\x5Cd{4})-(\x5Cd{2})-(\x5Cd{2})(?:\x5Cs.*)?$/\x27\x2C $raw\x2C $m)) {
 $year = (int) $m[1]\x3B
 $month = (int) $m[2]\x3B
 $day = (int) $m[3]\x3B

 if (!checkdate($month\x2C $day\x2C $year)) {
 return \x27\x27\x3B
 }

 return sprintf(\x27%02d/%02d/%04d\x27\x2C $day\x2C $month\x2C $year)\x3B
 }

 // 2) Normalisation des espaces autour des séparateurs
 // ex: \x2212/ 02/2023\x22\x2C \x2215- 03 / 26\x22\x2C \x2212 / 02 / 2023\x22
 $normalized = preg_replace(\x27/\x5Cs*([\x5C/-])\x5Cs*/\x27\x2C \x27$1\x27\x2C $raw)\x3B
 $normalized = trim((string) $normalized)\x3B

 // 3) Cas FR ou mixte : j/m/aa\x2C jj-mm-aaaa\x2C etc.
 if (preg_match(\x27/^(\x5Cd{1\x2C2})[\x5C/-](\x5Cd{1\x2C2})[\x5C/-](\x5Cd{2}|\x5Cd{4})$/\x27\x2C $normalized\x2C $m)) {
 $day = (int) $m[1]\x3B
 $month = (int) $m[2]\x3B
 $year = (int) $m[3]\x3B

 // Conversion année sur 2 chiffres
 if (strlen($m[3]) === 2) {
 // Règle correspondant à tes tests :
 // 00..26 =\x3E 2000..2026
 // 27..99 =\x3E 1927..1999
 $year = ($year \x3C= 26) ? (2000 + $year) : (1900 + $year)\x3B
 }

 if (!checkdate($month\x2C $day\x2C $year)) {
 return \x27\x27\x3B
 }

 return sprintf(\x27%02d/%02d/%04d\x27\x2C $day\x2C $month\x2C $year)\x3B
 }

 // Format non reconnu
 return \x27\x27\x3B
}

piece.description:
Extrait l\x27Email du User Joomla courant

// Gilles - 15/01/2026
// Extrait l\x27EMAIL du User Joomla courant
// - Supprime les espaces parasites (trim)
// - Force en minuscules (normalisation)
// - Filtre les caractères invalides (sécurité)
// Utilisable pour : exports VCMB\x2C CSV\x2C envois mail\x2C FFVélo\x2C etc.
// Compatible Joomla 6 / PHP 8.x
// Gilles — 24/03/2026

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_email($email = \x27\x27)
 * ------------------------------------------------
 * Retourne un email normalisé :
 * - source : paramètre ou utilisateur Joomla
 * - trim + minuscules
 * - nettoyage des caractères invalides
 *
 * Retour :
 * - email normalisé
 * - \x27\x27 si non disponible
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */
function gn_get_vcmb_email($email = \x27\x27): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Si aucun email fourni → utilisateur Joomla
 // ------------------------------------------------
 if ($email === null || trim((string) $email) === \x27\x27) {

 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_email: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 if (empty($user-\x3Eemail)) {
 return \x27\x27\x3B
 }

 $email = (string) $user-\x3Eemail\x3B
 }

 // ------------------------------------------------
 // Nettoyage
 // ------------------------------------------------
 $email = trim((string) $email)\x3B

 if ($email === \x27\x27) {
 return \x27\x27\x3B
 }

 // Normalisation en minuscules
 $email = strtolower($email)\x3B

 // Nettoyage caractères invalides
 $email = filter_var($email\x2C FILTER_SANITIZE_EMAIL)\x3B

 // ------------------------------------------------
 // Validation (optionnelle mais recommandée)
 // ------------------------------------------------
 if (!filter_var($email\x2C FILTER_VALIDATE_EMAIL)) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_email: invalid email=\x27 . $email)\x3B
 }
 return \x27\x27\x3B
 }

 return $email\x3B

} // gn_get_vcmb_email

