 * \x22GRAVEL\x22
 *
 * Fonctionnement :
 * - si utilisateur non connecté → retourne \x27\x27
 * - lit les champs custom utilisateur Joomla
 * - cherche le champ demandé
 * - vérifie qu\x27il est bien de type \x22list\x22
 * - retourne la valeur sélectionnée
 * - fallback si tableau (cas rare)
 * - si champ non trouvé → retourne \x27\x27
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */

function gn_get_vcmb_groupe($fieldName = \x27groupe-vcmb\x27): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Type attendu du champ
 // ------------------------------------------------
 $fieldType = \x27list\x27\x3B

 // ------------------------------------------------
 // Utilisateur courant
 // ------------------------------------------------
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eget(\x27id\x27) === 0) {
