 // ------------------------------------------------
 $fields = FieldsHelper::getFields(\x27com_users.user\x27\x2C $user\x2C true)\x3B

 // ------------------------------------------------
 // Recherche du champ demandé
 // ------------------------------------------------
 foreach ($fields as $field) {

 if ($field-\x3Ename === $fieldName \x26\x26 $field-\x3Etype === $fieldType) {

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_groupe: field found [\x27 . $fieldName . \x27]\x27)\x3B
 }

 // Cas normal : champ list = string
 if (is_array($field-\x3Erawvalue)) {
