// Gilles - 24/03/2026

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CComponent\x5CFields\x5CAdministrator\x5CHelper\x5CFieldsHelper\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_groupes($fieldName = \x27groupes-vcmb\x27)
 * ------------------------------------------------
 * Lit un champ utilisateur personnalisé Joomla
 * de type \x22checkboxes\x22 et retourne les valeurs
 * sélectionnées sous forme de chaîne séparée
 * par des points-virgules.
 *
 * Exemple :
 * [\x22ROUTE\x22\x2C \x22GRAVEL\x22\x2C \x22VTT\x22]
 * -\x3E \x22ROUTE\x3BGRAVEL\x3BVTT\x22
 *
 * Fonctionnement :
 * - si utilisateur non connecté → retourne \x27\x27
 * - lit les champs custom du profil utilisateur
 * - cherche le champ demandé par son nom
 * - vérifie qu\x27il est bien de type \x22checkboxes\x22
 * - si plusieurs valeurs → les concatène avec \x3B
 * - si une seule valeur → retourne cette valeur
 * - si champ non trouvé → retourne \x27\x27
 *
 * Compatible Joomla 6 / PHP 8.x / BF
 * ------------------------------------------------
 */

function gn_get_vcmb_groupes($fieldName = \x27groupes-vcmb\x27) : string
{
 // ------------------------------------------------
 // Type attendu du champ Joomla
 // ------------------------------------------------
 $fieldType = \x27checkboxes\x27\x3B

 // ------------------------------------------------
 // Utilisateur courant Joomla
 // ------------------------------------------------
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eget(\x27id\x27) === 0) {
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // Lecture des champs personnalisés utilisateur
 // com_users.user = contexte des champs user Joomla
 // true = valeurs préparées / chargées
 // ------------------------------------------------
 $fields = FieldsHelper::getFields(\x27com_users.user\x27\x2C $user\x2C true)\x3B

 // ------------------------------------------------
 // Recherche du champ demandé
 // ------------------------------------------------
 foreach ($fields as $field) {

 // Vérifie le nom du champ + son type attendu
 if ($field-\x3Ename === $fieldName \x26\x26 $field-\x3Etype === $fieldType) {

 // Cas normal d\x27un champ checkboxes :
 // rawvalue est un tableau de valeurs
 if (is_array($field-\x3Erawvalue)) {
 $vals = array_map(\x27trim\x27\x2C $field-\x3Erawvalue)\x3B
 return implode(\x27\x3B\x27\x2C $vals)\x3B
 }

 // Cas de repli :
 // si rawvalue n\x27est pas un tableau
 return trim((string) $field-\x3Erawvalue)\x3B
 }
 }

 // ------------------------------------------------
 // Champ non trouvé
 // ------------------------------------------------
 return \x27\x27\x3B

} // gn_get_vcmb_groupes

