// Joomla 6 / PHP 8.x / BreezingForms safe
// ------------------------------------------------------------

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CDatabase\x5CParameterType\x3B
use Joomla\x5CDatabase\x5CDatabaseInterface\x3B

function gn_get_vcmb_nb_inscrits(int $formId): int
{
 // ------------------------------------------------
 // GN - Compte le nombre d\x27inscrits d\x27un formulaire BF
 // Version 1.1 - 24/03/2026
 // Retourne 0 si formId invalide ou erreur SQL
 // ------------------------------------------------

 if ($formId \x3C= 0) {
 return 0\x3B
 }

 try {
 $db = Factory::getContainer()-\x3Eget(DatabaseInterface::class)\x3B

 $query = $db-\x3EgetQuery(true)
 -\x3Eselect(\x27COUNT(*)\x27)
 -\x3Efrom($db-\x3EquoteName(\x27#__facileforms_records\x27))
 -\x3Ewhere($db-\x3EquoteName(\x27form\x27) . \x27 = :formid\x27)
 -\x3Ebind(\x27:formid\x27\x2C $formId\x2C ParameterType::INTEGER)\x3B

 $db-\x3EsetQuery($query)\x3B

 return (int) $db-\x3EloadResult()\x3B

 } catch (\x5CThrowable $e) {
 return 0\x3B
 }

} // gn_get_vcmb_nb_inscrits

piece.description:
Extrait le NOM du User VCMB (username) : NOM Prénom

// Extrait le NOM (VCMB) du champ Joomla \x22name\x22 au format : \x22NOM Prénom\x22
// Hypothèse VCMB :
// - Le prénom est le DERNIER mot
// - Le nom peut contenir des espaces (LE ROUX\x2C DE LA ROUE\x2C etc.)
// Gère les accents (UTF-8) et les espaces multiples
// Si utilisateur non connecté → retourne \x27\x27
// Gilles — 24/03/2026

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_nom($name = \x27\x27)
 * ------------------------------------------------
 * Retourne le NOM (majuscule) à partir du nom complet
 * Joomla au format habituel :
 *
 * \x22NOM Prénom\x22
 *
 * Exemples :
 * \x22LE ROUX Jean-Luc\x22 -\x3E \x22LE ROUX\x22
 * \x22DUPONT Pierre\x22 -\x3E \x22DUPONT\x22
 *
 * Fonctionnement :
 * - si $name est vide → lit le nom utilisateur Joomla
 * - si utilisateur non connecté → retourne \x27\x27
 * - supprime le prénom (dernier mot)
 * - retourne le NOM en majuscules UTF-8
 *
 * Compatible accents : É È Ç À etc.
 * ------------------------------------------------
 */
function gn_get_vcmb_nom($name = \x27\x27): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Si aucun nom fourni → lire utilisateur Joomla
 // ------------------------------------------------
 if ($name === null || trim((string) $name) === \x27\x27) {

 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_nom: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $name = (string) $user-\x3Ename\x3B

 if ($name === \x27\x27) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_nom: empty user name\x27)\x3B
 }
 return \x27\x27\x3B
 }
 }

 // ------------------------------------------------
 // Nettoyage de base
 // ------------------------------------------------
 $full = trim((string) $name)\x3B

 if ($full === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_nom: raw=\x27 . $full)\x3B
 }

 // ------------------------------------------------
 // Découpe sur espaces
 // ------------------------------------------------
 $parts = preg_split(\x27/\x5Cs+/u\x27\x2C $full\x2C -1\x2C PREG_SPLIT_NO_EMPTY)\x3B

 // Si pas NOM + prénom → retourne tout en MAJ
 if (!$parts || count($parts) \x3C 2) {
 return mb_strtoupper($full\x2C \x27UTF-8\x27)\x3B
 }

 // ------------------------------------------------
 // Supprime le prénom (dernier mot)
 // ------------------------------------------------
 array_pop($parts)\x3B

 // NOM reconstitué
 $nom = implode(\x27 \x27\x2C $parts)\x3B

 // ------------------------------------------------
 // Retour NOM en majuscules UTF-8
 // ------------------------------------------------
 $nom = mb_strtoupper($nom\x2C \x27UTF-8\x27)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_nom: normalized=\x27 . $nom)\x3B
 }

 return $nom\x3B

} // gn_get_vcmb_nom

piece.description:
Extrait le Prénom du User VCMB (username) : NOM Prénom

// Extrait le PRÉNOM (VCMB) du champ Joomla \x22name\x22 au format : \x22NOM Prénom\x22
// Hypothèse VCMB :
// - Le prénom est le DERNIER mot
// - Le nom peut contenir des espaces (LE ROUX\x2C DE LA ROUE\x2C etc.)
// Gère les accents (UTF-8) et les prénoms composés (Jean-Luc\x2C Marie-Claire)
// Si utilisateur non connecté → retourne \x27\x27
// Gilles - 24/03/2026

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B

/**
 * ------------------------------------------------
 * gn_get_vcmb_prenom($name=\x27\x27)
 * ------------------------------------------------
 * Retourne le prénom à partir du nom complet Joomla
 *
 * Format attendu :
 * \x22NOM Prénom\x22
 *
 * Exemples :
 * \x22LE ROUX Jean-Luc\x22 -\x3E \x22Jean-Luc\x22
 * \x22DUPONT Pierre\x22 -\x3E \x22Pierre\x22
 *
 * Fonctionnement :
 * - si $name vide → lit le nom utilisateur Joomla
 * - si utilisateur non connecté → retourne \x27\x27
 * - le prénom = dernier mot
 * - formatte joliment (Jean-Luc\x2C Élodie...)
 * ------------------------------------------------
 */

function gn_get_vcmb_prenom($name = \x27\x27): string
{
 $GN_DEBUG = false\x3B

 // ------------------------------------------------
 // Si aucun nom fourni → lire utilisateur Joomla
 // ------------------------------------------------
 if ($name === null || trim((string)$name) === \x27\x27) {

 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int)$user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_prenom: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $name = (string) $user-\x3Ename\x3B

 if ($name === \x27\x27) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_prenom: empty user name\x27)\x3B
 }
 return \x27\x27\x3B
 }
 }

 // ------------------------------------------------
 // Nettoyage
 // ------------------------------------------------
 $full = trim((string)$name)\x3B

 if ($full === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_prenom: raw=\x27 . $full)\x3B
 }

 // ------------------------------------------------
 // Découpe sur espaces
 // ------------------------------------------------
 $parts = preg_split(\x27/\x5Cs+/u\x27\x2C $full\x2C -1\x2C PREG_SPLIT_NO_EMPTY)\x3B

 if (!$parts || count($parts) \x3C 2) {
 return \x27\x27\x3B
 }

 // ------------------------------------------------
 // Prénom = dernier mot
 // ------------------------------------------------
 $firstname = (string) end($parts)\x3B

 // ------------------------------------------------
 // Mise en forme améliorée
 // ------------------------------------------------
 $firstname = _gn_get_vcmb_format_prenom($firstname)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_prenom: normalized=\x27 . $firstname)\x3B
 }

 return $firstname\x3B

} // gn_get_vcmb_prenom


// ------------------------------------------------
// Format prénom propre FR (Jean-Luc\x2C D\x27Angelo\x2C Élodie)
// ------------------------------------------------
function _gn_get_vcmb_format_prenom(string $name): string
{
 $name = mb_strtolower($name\x2C \x27UTF-8\x27)\x3B

 // Gestion des tirets (Jean-Luc)
 $parts = explode(\x27-\x27\x2C $name)\x3B
 $parts = array_map(function ($p) {

 // Gestion apostrophe (d\x27Angelo)
 $sub = explode(\x22\x27\x22\x2C $p)\x3B
 $sub = array_map(function ($s) {
 return mb_convert_case($s\x2C MB_CASE_TITLE\x2C \x27UTF-8\x27)\x3B
 }\x2C $sub)\x3B

 return implode(\x22\x27\x22\x2C $sub)\x3B

 }\x2C $parts)\x3B

 return implode(\x27-\x27\x2C $parts)\x3B

} // _gn_get_vcmb_format_prenom

piece.description:
Extrait \x22Téléphone\x22 du Joomla User Profile VCMB (phone)

// Gilles - 24/03/2026
// Get Joomla PROFILE field \x22phone\x22 (profile.phone)
// Not a Joomla custom field (UF) -\x3E do NOT use FieldsHelper here
// Return empty string if not logged in or field not found
// VCMB normalization: French phone format \x2206 88 88 77 77\x22
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CCMS\x5CUser\x5CUserHelper\x3B

function gn_get_vcmb_telephone($phonenumber = \x27\x27): string
{
 // ------------------------------------------------
 // GN - Téléphone utilisateur Joomla / profil
 // Version 1.1 - 24/03/2026
 // - protection si non connecté
 // - lecture profil Joomla
 // - normalisation FR (+33 / 0033 / espaces / tirets / points)
 // ------------------------------------------------

 $GN_DEBUG = false\x3B
 $profileField = \x27phone\x27\x3B

 // Si aucun téléphone fourni\x2C on tente de lire celui du profil utilisateur connecté
 if ($phonenumber === null || trim((string) $phonenumber) === \x27\x27) {

 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_telephone: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $profile = UserHelper::getProfile((int) $user-\x3Eid)\x3B

 if (
 !isset($profile-\x3Eprofile) ||
 !is_array($profile-\x3Eprofile) ||
 !array_key_exists($profileField\x2C $profile-\x3Eprofile)
 ) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_telephone: profile field not found [\x27 . $profileField . \x27]\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $phonenumber = (string) $profile-\x3Eprofile[$profileField]\x3B
 }

 $tel = trim((string) $phonenumber)\x3B

 if ($tel === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_telephone: raw=\x27 . $tel)\x3B
 }

 $tel = _gn_get_vcmb_normalize_phone($tel)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_telephone: normalized=\x27 . $tel)\x3B
 }

 return $tel\x3B

} // gn_get_vcmb_telephone


// ------------------------------------------------
// Gilles - 24/03/2026
// Normalise un téléphone français au format : 06 88 88 77 77
// Accepte : +33\x2C 0033\x2C espaces\x2C points\x2C tirets\x2C parenthèses
// Si format non reconnu\x2C retourne les chiffres \x22nets\x22
// ------------------------------------------------
function _gn_get_vcmb_normalize_phone($phonenumber): string
{
 $s = trim((string) $phonenumber)\x3B

 if ($s === \x27\x27) {
 return \x27\x27\x3B
 }

 // Conserve uniquement les chiffres
 $s = preg_replace(\x27/\x5CD+/\x27\x2C \x27\x27\x2C $s)\x3B

 if ($s === \x27\x27) {
 return \x27\x27\x3B
 }

 // 0033XXXXXXXXX -\x3E 0XXXXXXXXX
 if (strpos($s\x2C \x270033\x27) === 0) {
 $s = \x270\x27 . substr($s\x2C 4)\x3B
 }
 // 33XXXXXXXXX -\x3E 0XXXXXXXXX
 elseif (strpos($s\x2C \x2733\x27) === 0) {
 $s = \x270\x27 . substr($s\x2C 2)\x3B
 }

 // Si on obtient bien 10 chiffres FR\x2C on formate
 if (preg_match(\x27/^0\x5Cd{9}$/\x27\x2C $s)) {
 return preg_replace(\x27/(\x5Cd{2})(\x5Cd{2})(\x5Cd{2})(\x5Cd{2})(\x5Cd{2})/\x27\x2C \x27$1 $2 $3 $4 $5\x27\x2C $s)\x3B
 }

 // Fallback : retourne les chiffres bruts
 return $s\x3B

} // _gn_get_vcmb_normalize_phone

piece.description:
Extrait \x22Ville\x22 du Joomla User Profile VCMB (city)

// Gilles - 24/03/2026
// Get Joomla PROFILE field \x22city\x22 (profile.city)
// Not a Joomla custom field (UF) -\x3E do NOT use FieldsHelper here
// Return empty string if not logged in or field not found
// VCMB normalization: Montigny-le-Bretonneux style
// Joomla 6 / PHP 8.x / BreezingForms safe

piece.code:
use Joomla\x5CCMS\x5CFactory\x3B
use Joomla\x5CCMS\x5CUser\x5CUserHelper\x3B

function gn_get_vcmb_ville($town = \x27\x27): string
{
 // ------------------------------------------------
 // GN - Ville utilisateur Joomla / profil
 // Version 1.2 - 24/03/2026
 // - protection si non connecté
 // - lecture profil Joomla
 // - normalisation ville FR
 // ------------------------------------------------

 $GN_DEBUG = false\x3B
 $profileField = \x27city\x27\x3B

 if ($town === null || trim((string) $town) === \x27\x27) {

 // Utilisateur courant
 $user = Factory::getApplication()-\x3EgetIdentity()\x3B

 // sécurité : utilisateur non connecté
 if ((int) $user-\x3Eid === 0) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_ville: user not logged in\x27)\x3B
 }
 return \x27\x27\x3B
 }

 // Charge le profil Joomla
 $profile = UserHelper::getProfile((int) $user-\x3Eid)\x3B

 if (
 !isset($profile-\x3Eprofile) ||
 !is_array($profile-\x3Eprofile) ||
 !array_key_exists($profileField\x2C $profile-\x3Eprofile)
 ) {
 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_ville: profile field not found [\x27 . $profileField . \x27]\x27)\x3B
 }
 return \x27\x27\x3B
 }

 $town = (string) $profile-\x3Eprofile[$profileField]\x3B
 }

 $city = trim((string) $town)\x3B

 if ($city === \x27\x27) {
 return \x27\x27\x3B
 }

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_ville: raw=\x27 . $city)\x3B
 }

 // Normalisation VCMB
 $city = _gn_get_vcmb_normalize_ville($city)\x3B

 if ($GN_DEBUG) {
 error_log(\x27[BF] gn_get_vcmb_ville: normalized=\x27 . $city)\x3B
 }

 return $city\x3B

} // gn_get_vcmb_ville


// ------------------------------------------------
// Gilles - 24/03/2026
// Normalise un nom de ville avec règles VCMB
// Règles :
// 1) Mise en forme générale en Title Case UTF-8
// 2) Certains petits mots restent en minuscule sauf en 1re position
// 3) Les mots composés gardent les tirets
// 4) Cas spécial : \x22Le-\x22 en début devient \x22Le \x22
// 5) Gère les apostrophes : L\x27Isle-Adam
// Ex :
// MONTIGNY-LE-BRETONNEUX -\x3E Montigny-le-Bretonneux
// LE MANET-DU-ROI -\x3E Le Manet-du-Roi
// L\x27ISLE-ADAM -\x3E L\x27Isle-Adam
// Joomla 6 / PHP 8.x / BreezingForms safe
// ------------------------------------------------
function _gn_get_vcmb_normalize_ville($town_name): string
{
 $s = trim((string) $town_name)\x3B

 if ($s === \x27\x27) {
 return \x27\x27\x3B
 }

 // Normalise espaces et tirets
 $s = preg_replace(\x27/\x5Cs*-\x5Cs*/u\x27\x2C \x27-\x27\x2C $s)\x3B
 $s = preg_replace(\x27/\x5Cs+/u\x27\x2C \x27 \x27\x2C $s)\x3B

 // Découpe en conservant séparateurs espace / tiret
 $tokens = preg_split(\x27/([\x5C- ])/u\x27\x2C $s\x2C -1\x2C PREG_SPLIT_DELIM_CAPTURE)\x3B

 $lowerWords = [\x27le\x27\x2C \x27la\x27\x2C \x27les\x27\x2C \x27de\x27\x2C \x27du\x27\x2C \x27des\x27\x2C \x27au\x27\x2C \x27aux\x27\x2C \x27sur\x27\x2C \x27sous\x27\x2C \x27lès\x27\x2C \x27en\x27\x2C \x27et\x27]\x3B

 $out = []\x3B
 $isFirst = true\x3B

 foreach ($tokens as $t) {

 // Conserve les séparateurs
 if ($t === \x27-\x27 || $t === \x27 \x27) {
 $out[] = $t\x3B
 continue\x3B
 }

 $tLower = mb_strtolower($t\x2C \x27UTF-8\x27)\x3B

 // Gère les apostrophes mot par mot : l\x27isle -\x3E L\x27Isle
 $subparts = explode(\x22\x27\x22\x2C $tLower)\x3B
 $subparts = array_map(function ($part) {
 return mb_convert_case($part\x2C MB_CASE_TITLE\x2C \x27UTF-8\x27)\x3B
 }\x2C $subparts)\x3B
 $tTitle = implode(\x22\x27\x22\x2C $subparts)\x3B

 if ($isFirst) {
 $out[] = $tTitle\x3B
 } else {
 if (in_array($tLower\x2C $lowerWords\x2C true)) {
 $out[] = $tLower\x3B
 } else {
 $out[] = $tTitle\x3B
 }
 }

 $isFirst = false\x3B
 }

 $s = implode(\x27\x27\x2C $out)\x3B

 // Cas spécial : \x22Le-\x22 au début devient \x22Le \x22
 $s = preg_replace(\x27/^Le-/u\x27\x2C \x27Le \x27\x2C $s)\x3B

 return $s\x3B

} // _gn_get_vcmb_normalize_ville
